import type { Question } from "../types";

export const GRADE7B_QUESTIONS: Question[] = [
  // ===== 生物 人教版 =====
  { id: "bio-7b-rj-001", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "人体生命活动所需要的能量主要来自食物中的（　　）", options: ["A. 糖类", "B. 脂肪", "C. 蛋白质", "D. 维生素"], answer: "A", analysis: "糖类是人体最主要的供能物质，人体生命活动所需要的能量约60%-70%来自糖类的氧化分解。", mastered: false, collected: false },
  { id: "bio-7b-rj-002", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "下列营养物质中，能为人体生命活动提供能量的是（　　）", options: ["A. 水", "B. 无机盐", "C. 维生素", "D. 糖类"], answer: "D", analysis: "糖类、脂肪、蛋白质能为人体提供能量，属于供能物质；水、无机盐、维生素不能为人体提供能量。", mastered: false, collected: false },
  { id: "bio-7b-rj-003", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "人体内主要的储能物质是（　　）", options: ["A. 糖类", "B. 脂肪", "C. 蛋白质", "D. 维生素"], answer: "B", analysis: "脂肪是人体内主要的储能物质，一般情况下贮存在皮下等处，当人体需要时可分解释放能量。", mastered: false, collected: false },
  { id: "bio-7b-rj-004", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "构成人体细胞的基本物质是（　　）", options: ["A. 糖类", "B. 脂肪", "C. 蛋白质", "D. 水"], answer: "C", analysis: "蛋白质是构成人体细胞的基本物质，与人体的生长发育以及受损细胞的修复和更新有密切关系。", mastered: false, collected: false },
  { id: "bio-7b-rj-005", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "下列关于维生素的叙述，正确的是（　　）", options: ["A. 是构成细胞的主要成分", "B. 能为人体提供能量", "C. 人体需要量少，但对生命活动至关重要", "D. 缺乏维生素A会得坏血病"], answer: "C", analysis: "维生素既不参与构成细胞，也不为人体提供能量，人体需要量很少，但对生命活动至关重要。缺乏维生素A会患夜盲症，缺乏维生素C才会得坏血病。", mastered: false, collected: false },
  { id: "bio-7b-rj-006", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "患坏血病的人应该多吃富含哪种维生素的食物（　　）", options: ["A. 维生素A", "B. 维生素B1", "C. 维生素C", "D. 维生素D"], answer: "C", analysis: "维生素C能维持人体正常的新陈代谢，缺乏时会引起坏血病，应多吃新鲜蔬菜和水果。", mastered: false, collected: false },
  { id: "bio-7b-rj-007", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "人体消化和吸收的主要场所是（　　）", options: ["A. 口腔", "B. 胃", "C. 小肠", "D. 大肠"], answer: "C", analysis: "小肠是人体消化食物和吸收营养物质的主要场所，它有环形皱襞和小肠绒毛，增大了吸收面积。", mastered: false, collected: false },
  { id: "bio-7b-rj-008", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "唾液淀粉酶能将淀粉分解为（　　）", options: ["A. 葡萄糖", "B. 麦芽糖", "C. 氨基酸", "D. 甘油和脂肪酸"], answer: "B", analysis: "唾液中含有唾液淀粉酶，能将淀粉分解为麦芽糖，麦芽糖再在小肠中被进一步分解为葡萄糖。", mastered: false, collected: false },
  { id: "bio-7b-rj-009", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "下列关于呼吸道功能的叙述，错误的是（　　）", options: ["A. 保证气体顺畅通过", "B. 对吸入气体进行处理", "C. 能使到达肺部的气体变得温暖、湿润、清洁", "D. 完成气体交换"], answer: "D", analysis: "呼吸道能保证气体顺畅通过，并对吸入的气体进行处理，使到达肺部的气体温暖、湿润、清洁。气体交换是在肺泡内完成的，不属于呼吸道功能。", mastered: false, collected: false },
  { id: "bio-7b-rj-010", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "人体与外界进行气体交换的场所是（　　）", options: ["A. 鼻腔", "B. 咽", "C. 喉", "D. 肺"], answer: "D", analysis: "肺是呼吸系统的主要器官，是人体与外界进行气体交换的场所。肺泡外缠绕着毛细血管，便于气体交换。", mastered: false, collected: false },
  { id: "bio-7b-rj-011", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "下列血管中，流动脉血的是（　　）", options: ["A. 肺动脉", "B. 肺静脉", "C. 上、下腔静脉", "D. 体动脉"], answer: "B", analysis: "肺静脉里流动的是动脉血（含氧丰富），肺动脉里流动的是静脉血（含氧较少）。动脉血和静脉血是根据含氧量来区分的，与血管名称无关。", mastered: false, collected: false },
  { id: "bio-7b-rj-012", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "心脏四个腔中，壁最厚的是（　　）", options: ["A. 左心房", "B. 左心室", "C. 右心房", "D. 右心室"], answer: "B", analysis: "左心室的壁最厚，因为左心室要把血液泵到全身各处，需要较大的收缩力。心房壁较薄，心室壁较厚。", mastered: false, collected: false },
  { id: "bio-7b-rj-013", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "人体形成尿液的器官是（　　）", options: ["A. 肾脏", "B. 输尿管", "C. 膀胱", "D. 尿道"], answer: "A", analysis: "肾脏是形成尿液的器官，输尿管输送尿液，膀胱贮存尿液，尿道排出尿液。", mastered: false, collected: false },
  { id: "bio-7b-rj-014", subject: "biology", grade: "七年级下册", version: "人教版", type: "single", stem: "神经系统结构和功能的基本单位是（　　）", options: ["A. 细胞体", "B. 神经元", "C. 神经纤维", "D. 神经"], answer: "B", analysis: "神经元又称神经细胞，是神经系统结构和功能的基本单位，包括细胞体和突起两部分。", mastered: false, collected: false },
  { id: "bio-7b-rj-015", subject: "biology", grade: "七年级下册", version: "人教版", type: "judge", stem: "森林的大量砍伐不会对生物圈造成影响。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "森林大量砍伐会破坏生态平衡，导致水土流失、气候异常、生物多样性减少等，对生物圈造成严重影响。", mastered: false, collected: false },

  // ===== 生物 人教版（2024）=====
  { id: "bio-7b-rj24-001", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "下列食物中，富含蛋白质的是（　　）", options: ["A. 米饭", "B. 馒头", "C. 鸡蛋", "D. 花生油"], answer: "C", analysis: "鸡蛋富含蛋白质；米饭、馒头主要含糖类；花生油主要含脂肪。", mastered: false, collected: false },
  { id: "bio-7b-rj24-002", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "儿童缺钙易患（　　）", options: ["A. 佝偻病", "B. 贫血", "C. 夜盲症", "D. 坏血病"], answer: "A", analysis: "儿童缺钙易患佝偻病，中老年人缺钙易患骨质疏松症。缺铁易患贫血，缺乏维生素A易患夜盲症。", mastered: false, collected: false },
  { id: "bio-7b-rj24-003", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "下列营养物质中，不经过消化就能直接被吸收的是（　　）", options: ["A. 淀粉", "B. 蛋白质", "C. 脂肪", "D. 水"], answer: "D", analysis: "水、无机盐、维生素是小分子物质，不需要消化就能直接被吸收；淀粉、蛋白质、脂肪是大分子物质，需要消化后才能被吸收。", mastered: false, collected: false },
  { id: "bio-7b-rj24-004", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "在人体消化道中，最早消化蛋白质的部位是（　　）", options: ["A. 口腔", "B. 胃", "C. 小肠", "D. 大肠"], answer: "B", analysis: "胃内有胃蛋白酶，能对蛋白质进行初步消化，小肠中有多种消化酶，能将蛋白质彻底分解为氨基酸。", mastered: false, collected: false },
  { id: "bio-7b-rj24-005", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "下列结构不属于消化道的是（　　）", options: ["A. 口腔", "B. 咽", "C. 肝脏", "D. 胃"], answer: "C", analysis: "消化道包括口腔、咽、食道、胃、小肠、大肠、肛门。肝脏属于消化腺，分泌胆汁，不属于消化道。", mastered: false, collected: false },
  { id: "bio-7b-rj24-006", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "胆汁是由哪个器官分泌的（　　）", options: ["A. 胃", "B. 肝脏", "C. 胰腺", "D. 肠腺"], answer: "B", analysis: "胆汁是由肝脏分泌的，储存在胆囊中，进入小肠后能乳化脂肪，但胆汁中不含消化酶。", mastered: false, collected: false },
  { id: "bio-7b-rj24-007", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "吸气时，膈肌和肋间肌的状态是（　　）", options: ["A. 膈肌收缩，肋间肌收缩", "B. 膈肌舒张，肋间肌舒张", "C. 膈肌收缩，肋间肌舒张", "D. 膈肌舒张，肋间肌收缩"], answer: "A", analysis: "吸气时膈肌收缩，膈顶下降，胸廓上下径增大；肋间肌收缩，肋骨上提，胸廓前后径和左右径增大，肺扩张，气体进入肺。", mastered: false, collected: false },
  { id: "bio-7b-rj24-008", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "肺泡外缠绕着丰富的毛细血管，这有利于（　　）", options: ["A. 肺泡与血液进行气体交换", "B. 营养物质的吸收", "C. 废物的排出", "D. 血液的过滤"], answer: "A", analysis: "肺泡壁和毛细血管壁都很薄，仅由一层上皮细胞构成，有利于肺泡与血液之间进行气体交换。", mastered: false, collected: false },
  { id: "bio-7b-rj24-009", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "下列关于动脉的叙述，正确的是（　　）", options: ["A. 管壁薄，弹性小", "B. 将血液从全身送回心脏", "C. 管壁厚，弹性大", "D. 血流速度最慢"], answer: "C", analysis: "动脉是将血液从心脏输送到全身各处的血管，管壁厚、弹性大、血流速度最快。", mastered: false, collected: false },
  { id: "bio-7b-rj24-010", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "血液中具有运输氧功能的是（　　）", options: ["A. 红细胞", "B. 白细胞", "C. 血小板", "D. 血浆"], answer: "A", analysis: "红细胞富含血红蛋白，血红蛋白在氧含量高的地方容易与氧结合，在氧含量低的地方容易与氧分离，具有运输氧的功能。", mastered: false, collected: false },
  { id: "bio-7b-rj24-011", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "下列血细胞中，具有止血和凝血功能的是（　　）", options: ["A. 红细胞", "B. 白细胞", "C. 血小板", "D. 血浆"], answer: "C", analysis: "血小板具有止血和加速凝血的功能。红细胞运输氧，白细胞防御和保护，血浆运输养料和废物。", mastered: false, collected: false },
  { id: "bio-7b-rj24-012", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "人体内最大的消化腺是（　　）", options: ["A. 唾液腺", "B. 胃腺", "C. 肠腺", "D. 肝脏"], answer: "D", analysis: "肝脏是人体内最大的消化腺，分泌胆汁，对脂肪起乳化作用。", mastered: false, collected: false },
  { id: "bio-7b-rj24-013", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "尿的形成是连续的，而尿的排出是间歇的，原因是（　　）", options: ["A. 肾小球滤过作用", "B. 肾小管重吸收作用", "C. 膀胱有贮尿功能", "D. 输尿管蠕动"], answer: "C", analysis: "肾脏形成尿液是连续的，尿液经输尿管流入膀胱贮存，当膀胱内尿液达到一定量时才排出，因此排尿是间歇的。", mastered: false, collected: false },
  { id: "bio-7b-rj24-014", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "下列反射中，属于简单反射的是（　　）", options: ["A. 谈虎色变", "B. 望梅止渴", "C. 缩手反射", "D. 望文生义"], answer: "C", analysis: "缩手反射是生来就有的简单反射，神经中枢在脊髓；谈虎色变、望梅止渴、望文生义都是后天形成的复杂反射。", mastered: false, collected: false },
  { id: "bio-7b-rj24-015", subject: "biology", grade: "七年级下册", version: "人教版（2024）", type: "judge", stem: "呼吸道对吸入气体有清洁作用，因此即使空气污浊也不会对健康造成影响。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "呼吸道虽能对吸入气体进行清洁处理，但能力有限，长期吸入污浊空气仍会对呼吸道和肺造成伤害。", mastered: false, collected: false },

  // ===== 生物 北师大版 =====
  { id: "bio-7b-bnu-001", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列各项中，能正确表示人体内能量获得过程的是（　　）", options: ["A. 食物→消化→吸收→能量", "B. 食物→消化→吸收→细胞→能量", "C. 食物→吸收→消化→能量", "D. 食物→吸收→细胞→能量"], answer: "B", analysis: "人体通过消化系统摄取食物，经消化吸收后，营养物质进入细胞，在细胞内氧化分解释放能量，供生命活动需要。", mastered: false, collected: false },
  { id: "bio-7b-bnu-002", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列食物成分中，在胃中被初步消化的是（　　）", options: ["A. 淀粉", "B. 蛋白质", "C. 脂肪", "D. 维生素"], answer: "B", analysis: "胃液中含有胃蛋白酶，能对蛋白质进行初步消化。淀粉在口腔开始消化，脂肪在小肠开始消化，维生素不需消化。", mastered: false, collected: false },
  { id: "bio-7b-bnu-003", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列食物中，含维生素C最丰富的是（　　）", options: ["A. 猪肝", "B. 鸡蛋", "C. 新鲜柑橘", "D. 大米"], answer: "C", analysis: "维生素C主要存在于新鲜蔬菜和水果中，柑橘富含维生素C。动物肝脏、鸡蛋主要含维生素A，大米主要含糖类。", mastered: false, collected: false },
  { id: "bio-7b-bnu-004", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列消化液中，能消化淀粉但不消化蛋白质的是（　　）", options: ["A. 唾液", "B. 胃液", "C. 胰液", "D. 肠液"], answer: "A", analysis: "唾液中含有唾液淀粉酶，能消化淀粉，不含蛋白酶，不能消化蛋白质。胃液含胃蛋白酶，胰液和肠液含多种消化酶。", mastered: false, collected: false },
  { id: "bio-7b-bnu-005", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列关于肺的叙述，正确的是（　　）", options: ["A. 肺位于胸腔内", "B. 左肺有三叶", "C. 右肺有两叶", "D. 肺是消化器官"], answer: "A", analysis: "肺位于胸腔内，左右各一，左肺两叶，右肺三叶。肺是呼吸器官，不是消化器官。", mastered: false, collected: false },
  { id: "bio-7b-bnu-006", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列关于肺泡适于气体交换特点的叙述，错误的是（　　）", options: ["A. 数目多", "B. 壁薄", "C. 外缠毛细血管", "D. 壁厚"], answer: "D", analysis: "肺泡壁很薄，仅由一层上皮细胞构成，有利于气体交换。肺泡数目多、外缠毛细血管、壁薄都是适于气体交换的特点。", mastered: false, collected: false },
  { id: "bio-7b-bnu-007", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列关于血液循环的叙述，正确的是（　　）", options: ["A. 体循环和肺循环同时进行", "B. 体循环在先，肺循环在后", "C. 肺循环在先，体循环在后", "D. 两种循环交替进行"], answer: "A", analysis: "体循环和肺循环是同时进行的，它们在心脏处汇合，构成一条完整的循环途径。", mastered: false, collected: false },
  { id: "bio-7b-bnu-008", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列血管中，血流速度最慢的是（　　）", options: ["A. 动脉", "B. 静脉", "C. 毛细血管", "D. 主动脉"], answer: "C", analysis: "毛细血管管径最小，仅允许红细胞单行通过，管壁最薄，血流速度最慢，便于血液与组织细胞进行物质交换。", mastered: false, collected: false },
  { id: "bio-7b-bnu-009", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列关于输血的叙述，正确的是（　　）", options: ["A. 任何人都可以献血", "B. 输血以输同型血为原则", "C. O型血可以大量输给任何人", "D. AB型血可以接受任何血型的血"], answer: "B", analysis: "输血以输同型血为原则。O型血少量输给其他血型的人，AB型血可少量接受其他血型，但都不能大量输血。", mastered: false, collected: false },
  { id: "bio-7b-bnu-010", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列关于肾单位的叙述，正确的是（　　）", options: ["A. 由肾小球和肾小囊组成", "B. 由肾小管和肾小球组成", "C. 由肾小球、肾小囊和肾小管组成", "D. 由肾脏和输尿管组成"], answer: "C", analysis: "肾单位是肾脏结构和功能的基本单位，由肾小球、肾小囊和肾小管组成。", mastered: false, collected: false },
  { id: "bio-7b-bnu-011", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "原尿与血浆相比，原尿中不含（　　）", options: ["A. 葡萄糖", "B. 无机盐", "C. 大分子蛋白质", "D. 水"], answer: "C", analysis: "原尿是血液流经肾小球时滤过到肾小囊中的液体，与血浆相比，原尿中不含大分子蛋白质，因为蛋白质不能滤过。", mastered: false, collected: false },
  { id: "bio-7b-bnu-012", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列关于眼球结构的叙述，正确的是（　　）", options: ["A. 视网膜是视觉感受器", "B. 角膜能调节晶状体曲度", "C. 瞳孔能感受光刺激", "D. 晶状体能调节进入眼内光量"], answer: "A", analysis: "视网膜上有感光细胞，是视觉感受器。睫状体调节晶状体曲度，瞳孔调节进入眼内光量，角膜有折光作用。", mastered: false, collected: false },
  { id: "bio-7b-bnu-013", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列反射活动中，神经中枢在大脑皮层的是（　　）", options: ["A. 眨眼反射", "B. 排尿反射", "C. 膝跳反射", "D. 望梅止渴"], answer: "D", analysis: "望梅止渴是后天形成的复杂反射，神经中枢在大脑皮层。眨眼反射、排尿反射、膝跳反射都是简单反射，神经中枢在脊髓或脑干。", mastered: false, collected: false },
  { id: "bio-7b-bnu-014", subject: "biology", grade: "七年级下册", version: "北师大版", type: "single", stem: "下列腺体中，属于内分泌腺的是（　　）", options: ["A. 唾液腺", "B. 汗腺", "C. 甲状腺", "D. 肠腺"], answer: "C", analysis: "内分泌腺没有导管，分泌物直接进入血液。甲状腺是内分泌腺。唾液腺、汗腺、肠腺都有导管，属于外分泌腺。", mastered: false, collected: false },
  { id: "bio-7b-bnu-015", subject: "biology", grade: "七年级下册", version: "北师大版", type: "judge", stem: "神经元受到刺激后能产生神经冲动，并能传导神经冲动。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "神经元受到刺激后能产生神经冲动，并能将神经冲动传导到其他神经元或效应器，这是神经元的基本功能。", mastered: false, collected: false },

  // ===== 生物 苏教版 =====
  { id: "bio-7b-sj-001", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列说法中，正确的是（　　）", options: ["A. 维生素是构成细胞的主要成分", "B. 人体内的水主要来自饮水", "C. 蛋白质是人体最重要的供能物质", "D. 无机盐是人体最主要的能源物质"], answer: "B", analysis: "人体内的水主要来自饮水和食物，其次来自物质代谢产生的水。维生素不构成细胞，也不供能；糖类才是最主要的供能物质。", mastered: false, collected: false },
  { id: "bio-7b-sj-002", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "缺乏维生素A容易患（　　）", options: ["A. 脚气病", "B. 夜盲症", "C. 坏血病", "D. 佝偻病"], answer: "B", analysis: "维生素A能促进视觉细胞内感光物质的合成，缺乏时容易患夜盲症。脚气病缺维生素B1，坏血病缺维生素C，佝偻病缺钙或维生素D。", mastered: false, collected: false },
  { id: "bio-7b-sj-003", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列食物中含铁丰富的是（　　）", options: ["A. 菠菜", "B. 海带", "C. 猪肝", "D. 牛奶"], answer: "C", analysis: "动物肝脏如猪肝含铁丰富，铁是构成血红蛋白的重要成分，缺铁易患贫血。", mastered: false, collected: false },
  { id: "bio-7b-sj-004", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列器官中，既有消化功能又有吸收功能的是（　　）", options: ["A. 口腔", "B. 食道", "C. 胃", "D. 肝脏"], answer: "C", analysis: "胃能分泌胃液消化蛋白质，也能吸收少量水和无机盐。口腔只有消化功能，食道既无消化也无吸收功能，肝脏只有消化功能。", mastered: false, collected: false },
  { id: "bio-7b-sj-005", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "小肠绒毛内分布着丰富的毛细血管，其作用是（　　）", options: ["A. 分泌消化液", "B. 吸收营养物质", "C. 运输消化液", "D. 形成粪便"], answer: "B", analysis: "小肠绒毛内有丰富的毛细血管和毛细淋巴管，能将吸收的营养物质运送到全身各处。", mastered: false, collected: false },
  { id: "bio-7b-sj-006", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列结构中，不属于呼吸道的是（　　）", options: ["A. 鼻", "B. 咽", "C. 喉", "D. 肺"], answer: "D", analysis: "呼吸系统包括呼吸道和肺，呼吸道包括鼻、咽、喉、气管、支气管。肺是呼吸系统的主要器官，不属于呼吸道。", mastered: false, collected: false },
  { id: "bio-7b-sj-007", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列关于用鼻呼吸的优越性，错误的是（　　）", options: ["A. 鼻毛能阻挡灰尘", "B. 鼻黏膜能温暖吸入气体", "C. 鼻黏膜分泌黏液能湿润气体", "D. 鼻腔能完成气体交换"], answer: "D", analysis: "用鼻呼吸时，鼻毛阻挡灰尘，鼻黏膜温暖和湿润吸入气体，使到达肺部的气体清洁、温暖、湿润。气体交换在肺泡完成。", mastered: false, collected: false },
  { id: "bio-7b-sj-008", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列关于血液成分的叙述，正确的是（　　）", options: ["A. 红细胞有细胞核", "B. 白细胞能吞噬病菌", "C. 血小板能运输氧", "D. 血浆能止血"], answer: "B", analysis: "成熟的红细胞没有细胞核，白细胞能吞噬病菌起防御保护作用，血小板止血凝血，血浆运输养料和废物。", mastered: false, collected: false },
  { id: "bio-7b-sj-009", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "心脏的四个腔中，相通的是（　　）", options: ["A. 左心房与右心房", "B. 左心室与右心室", "C. 左心房与左心室", "D. 左心房与右心室"], answer: "C", analysis: "心脏左侧和右侧不相通，同侧的心房和心室相通。左心房与左心室相通，右心房与右心室相通。心房和心室之间有瓣膜防止血液倒流。", mastered: false, collected: false },
  { id: "bio-7b-sj-010", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列血管中，能进行物质交换的是（　　）", options: ["A. 动脉", "B. 静脉", "C. 毛细血管", "D. 主动脉"], answer: "C", analysis: "毛细血管壁很薄，血流速度慢，便于血液与组织细胞之间进行物质交换。动脉和静脉管壁较厚，不适于物质交换。", mastered: false, collected: false },
  { id: "bio-7b-sj-011", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列关于肾脏的叙述，正确的是（　　）", options: ["A. 位于腹腔内", "B. 是贮存尿液的器官", "C. 是形成尿液的器官", "D. 只有一个"], answer: "C", analysis: "肾脏位于脊柱两侧，左右各一，是形成尿液的器官。膀胱是贮存尿液的器官。", mastered: false, collected: false },
  { id: "bio-7b-sj-012", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列关于眼球结构的叙述，正确的是（　　）", options: ["A. 巩膜是眼球最外层", "B. 脉络膜有感光细胞", "C. 视网膜是白色", "D. 角膜能调节瞳孔大小"], answer: "A", analysis: "眼球壁外膜包括巩膜和角膜，巩膜是眼球最外层呈白色。视网膜有感光细胞，角膜有折光作用。", mastered: false, collected: false },
  { id: "bio-7b-sj-013", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列关于反射弧的叙述，正确的是（　　）", options: ["A. 感受器能产生感觉", "B. 传入神经传导神经冲动到效应器", "C. 神经中枢对刺激作出反应", "D. 效应器产生感觉"], answer: "C", analysis: "反射弧包括感受器、传入神经、神经中枢、传出神经、效应器五部分。感受器感受刺激产生神经冲动，神经中枢对刺激作出反应，效应器作出反应。", mastered: false, collected: false },
  { id: "bio-7b-sj-014", subject: "biology", grade: "七年级下册", version: "苏教版", type: "single", stem: "下列腺体中，分泌生长激素的是（　　）", options: ["A. 甲状腺", "B. 胰岛", "C. 垂体", "D. 肾上腺"], answer: "C", analysis: "垂体分泌生长激素，调节人体生长发育。甲状腺分泌甲状腺激素，胰岛分泌胰岛素，肾上腺分泌肾上腺素。", mastered: false, collected: false },
  { id: "bio-7b-sj-015", subject: "biology", grade: "七年级下册", version: "苏教版", type: "judge", stem: "婴幼儿时期甲状腺激素分泌不足会患呆小症。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "婴幼儿时期甲状腺激素分泌过少会患呆小症，表现为身材矮小、智力低下。成年人甲状腺激素分泌过多会患甲亢。", mastered: false, collected: false },

  // ===== 生物 苏科版 =====
  { id: "bio-7b-sk-001", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列食物中，含糖类较多的是（　　）", options: ["A. 瘦肉", "B. 米饭", "C. 植物油", "D. 蔬菜"], answer: "B", analysis: "米饭主要含糖类，是人体最主要的供能物质。瘦肉主要含蛋白质，植物油主要含脂肪，蔬菜含维生素和无机盐。", mastered: false, collected: false },
  { id: "bio-7b-sk-002", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于消化的叙述，正确的是（　　）", options: ["A. 消化是指大分子物质分解为小分子物质的过程", "B. 物理性消化需要酶参与", "C. 化学性消化不需要酶参与", "D. 胆汁能消化脂肪"], answer: "A", analysis: "消化是指食物中的大分子物质在消化道内分解为小分子物质的过程。物理性消化不需要酶，化学性消化需要酶。胆汁只对脂肪起乳化作用，不含消化酶。", mastered: false, collected: false },
  { id: "bio-7b-sk-003", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列食物成分中，能被人体直接吸收的是（　　）", options: ["A. 淀粉", "B. 蛋白质", "C. 脂肪", "D. 氨基酸"], answer: "D", analysis: "氨基酸是小分子物质，能被直接吸收。淀粉、蛋白质、脂肪是大分子物质，必须经过消化分解后才能被吸收。", mastered: false, collected: false },
  { id: "bio-7b-sk-004", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于胃的叙述，正确的是（　　）", options: ["A. 胃能分泌胆汁", "B. 胃是人体最长的消化器官", "C. 胃能初步消化蛋白质", "D. 胃是吸收营养的主要场所"], answer: "C", analysis: "胃能分泌胃液，胃液中含有胃蛋白酶，能初步消化蛋白质。胆汁由肝脏分泌，小肠是最长的消化器官和吸收营养的主要场所。", mastered: false, collected: false },
  { id: "bio-7b-sk-005", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于呼吸的叙述，正确的是（　　）", options: ["A. 呼吸就是指肺的通气", "B. 呼吸包括肺的通气和肺泡内的气体交换", "C. 呼吸就是肺泡内的气体交换", "D. 呼吸是气体进入肺的过程"], answer: "B", analysis: "呼吸包括肺的通气（肺与外界的气体交换）、肺泡内的气体交换、气体在血液中的运输、组织里的气体交换等过程。", mastered: false, collected: false },
  { id: "bio-7b-sk-006", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于膈肌的叙述，正确的是（　　）", options: ["A. 膈肌位于胸腔和腹腔之间", "B. 吸气时膈肌舒张", "C. 呼气时膈肌收缩", "D. 膈肌与呼吸无关"], answer: "A", analysis: "膈肌是胸腔和腹腔之间的肌肉。吸气时膈肌收缩，膈顶下降；呼气时膈肌舒张，膈顶上升，从而改变胸廓容积。", mastered: false, collected: false },
  { id: "bio-7b-sk-007", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于血红蛋白的叙述，正确的是（　　）", options: ["A. 含有铁元素", "B. 在氧多时易与氧分离", "C. 在氧少时易与氧结合", "D. 存在于血浆中"], answer: "A", analysis: "血红蛋白是一种含铁的蛋白质，存在于红细胞中。在氧含量高的地方易与氧结合，在氧含量低的地方易与氧分离。", mastered: false, collected: false },
  { id: "bio-7b-sk-008", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于心脏的叙述，正确的是（　　）", options: ["A. 心脏位于胸腔内", "B. 心脏位于腹腔内", "C. 心脏在胸腔正中", "D. 心脏位于两肺之间偏左下方"], answer: "D", analysis: "心脏位于胸腔内，两肺之间，偏左下方。心脏的大小与自己的拳头差不多。", mastered: false, collected: false },
  { id: "bio-7b-sk-009", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于体循环的途径，正确的是（　　）", options: ["A. 左心室→主动脉→全身各级动脉→全身毛细血管→各级静脉→上、下腔静脉→右心房", "B. 右心室→肺动脉→肺部毛细血管→肺静脉→左心房", "C. 左心房→左心室→全身各处", "D. 右心房→右心室→肺"], answer: "A", analysis: "体循环：左心室→主动脉→全身各级动脉→全身毛细血管（与组织细胞进行物质交换）→各级静脉→上、下腔静脉→右心房。", mastered: false, collected: false },
  { id: "bio-7b-sk-010", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于肾小球的叙述，正确的是（　　）", options: ["A. 肾小球是血管球", "B. 肾小球内有尿液", "C. 肾小球能重吸收", "D. 肾小球是肾小管的一部分"], answer: "A", analysis: "肾小球是由入球小动脉分支形成的毛细血管球，是滤过的场所。肾小囊包裹肾小球，肾小管有重吸收功能。", mastered: false, collected: false },
  { id: "bio-7b-sk-011", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列液体中，含葡萄糖最少的是（　　）", options: ["A. 血浆", "B. 原尿", "C. 尿液", "D. 组织液"], answer: "C", analysis: "原尿流经肾小管时，全部葡萄糖被重吸收回血液，因此尿液中不含葡萄糖。血浆和原尿都含葡萄糖。", mastered: false, collected: false },
  { id: "bio-7b-sk-012", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于耳的结构的叙述，正确的是（　　）", options: ["A. 外耳道是听觉感受器", "B. 鼓膜能感受声波", "C. 耳蜗内有听觉感受器", "D. 听小骨能产生听觉"], answer: "C", analysis: "耳蜗内有听觉感受器，能感受声波刺激产生神经冲动。鼓膜接受声波产生振动，听小骨传递振动。", mastered: false, collected: false },
  { id: "bio-7b-sk-013", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列关于反射的叙述，正确的是（　　）", options: ["A. 所有反射都必须经过反射弧", "B. 反射弧完整就能完成反射", "C. 反射活动不需要感受器", "D. 反射由感受器单独完成"], answer: "A", analysis: "反射是人体通过神经系统对外界或内部刺激作出的规律性反应，必须经过完整的反射弧才能完成。反射弧任何环节受损都不能完成反射。", mastered: false, collected: false },
  { id: "bio-7b-sk-014", subject: "biology", grade: "七年级下册", version: "苏科版", type: "single", stem: "下列激素中，能降低血糖浓度的是（　　）", options: ["A. 生长激素", "B. 甲状腺激素", "C. 胰岛素", "D. 肾上腺素"], answer: "C", analysis: "胰岛素由胰岛分泌，能促进血糖合成糖原，加速血糖分解，从而降低血糖浓度。", mastered: false, collected: false },
  { id: "bio-7b-sk-015", subject: "biology", grade: "七年级下册", version: "苏科版", type: "judge", stem: "人类活动对环境的影响都是负面的。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "人类活动对环境有正负两方面的影响。合理的人类活动能改善环境，如植树造林；不合理的人类活动会破坏环境，如乱砍滥伐。", mastered: false, collected: false },

  // ===== 生物 济南版 =====
  { id: "bio-7b-jn-001", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列说法中错误的是（　　）", options: ["A. 糖类是主要的供能物质", "B. 脂肪是主要的储能物质", "C. 蛋白质是构成细胞的基本物质", "D. 维生素是构成细胞的主要成分"], answer: "D", analysis: "维生素既不是构成细胞的主要成分，也不提供能量，但维持正常生命活动必不可少。糖类供能，脂肪储能，蛋白质构成细胞。", mastered: false, collected: false },
  { id: "bio-7b-jn-002", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列物质中，人体需要量大但既不构成细胞又不供能的是（　　）", options: ["A. 糖类", "B. 脂肪", "C. 水", "D. 维生素"], answer: "C", analysis: "水是人体需要量最大的营养物质，约占体重的60%-70%，但水既不构成细胞的主要成分，也不提供能量，是物质运输的主要介质。", mastered: false, collected: false },
  { id: "bio-7b-jn-003", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "消化腺分泌的消化液中，不含消化酶的是（　　）", options: ["A. 唾液", "B. 胃液", "C. 胆汁", "D. 胰液"], answer: "C", analysis: "胆汁由肝脏分泌，不含消化酶，但能乳化脂肪，使脂肪变成脂肪微粒，增加与脂肪酶的接触面积。", mastered: false, collected: false },
  { id: "bio-7b-jn-004", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于小肠适于消化吸收特点的叙述，错误的是（　　）", options: ["A. 小肠很长", "B. 内表面有皱襞和绒毛", "C. 肠液中有多种消化酶", "D. 肠壁仅有两层细胞"], answer: "D", analysis: "小肠适于消化吸收的特点：小肠很长，内表面有皱襞和小肠绒毛，增大了面积；肠液含多种消化酶；小肠绒毛壁很薄，仅一层上皮细胞。", mastered: false, collected: false },
  { id: "bio-7b-jn-005", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于肺通气的叙述，正确的是（　　）", options: ["A. 肺通气是肺与外界之间的气体交换", "B. 肺通气是肺泡与血液之间的气体交换", "C. 肺通气通过气体的扩散作用完成", "D. 肺通气通过呼吸运动实现"], answer: "A", analysis: "肺通气是指肺与外界之间的气体交换，通过呼吸运动实现。肺泡与血液之间的气体交换通过气体扩散作用完成。", mastered: false, collected: false },
  { id: "bio-7b-jn-006", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于呼气过程的叙述，正确的是（　　）", options: ["A. 膈肌收缩，膈顶下降", "B. 肋间肌收缩，肋骨上提", "C. 膈肌舒张，膈顶上升", "D. 胸廓扩大，肺扩张"], answer: "C", analysis: "呼气时，膈肌舒张，膈顶上升；肋间肌舒张，肋骨下降；胸廓缩小，肺回缩，肺内气压大于外界气压，气体被排出。", mastered: false, collected: false },
  { id: "bio-7b-jn-007", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列血管中，管壁最薄的是（　　）", options: ["A. 动脉", "B. 静脉", "C. 毛细血管", "D. 主动脉"], answer: "C", analysis: "毛细血管管壁最薄，仅由一层上皮细胞构成，便于物质交换。动脉和静脉管壁较厚，由多层组织构成。", mastered: false, collected: false },
  { id: "bio-7b-jn-008", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于ABO血型的叙述，正确的是（　　）", options: ["A. 血型由红细胞上的凝集原决定", "B. 血型由血浆中的凝集素决定", "C. 血型可随年龄改变", "D. 血型与遗传无关"], answer: "A", analysis: "ABO血型是由红细胞膜上的凝集原（抗原）类型决定的，有A凝集原的是A型，有B凝集原的是B型，两种都有的是AB型，都没有的是O型。", mastered: false, collected: false },
  { id: "bio-7b-jn-009", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于肾小囊的叙述，正确的是（　　）", options: ["A. 肾小囊有重吸收功能", "B. 肾小囊内有原尿", "C. 肾小囊能形成尿液", "D. 肾小囊与肾小管相通"], answer: "B", analysis: "肾小囊包裹在肾小球外面，肾小球滤过的液体进入肾小囊形成原尿。原尿流经肾小管时，肾小管进行重吸收。", mastered: false, collected: false },
  { id: "bio-7b-jn-010", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于肾小管重吸收的叙述，正确的是（　　）", options: ["A. 重吸收全部葡萄糖", "B. 重吸收全部水", "C. 不重吸收无机盐", "D. 不重吸收尿素"], answer: "A", analysis: "肾小管能重吸收全部葡萄糖、大部分水和部分无机盐，对尿素几乎不重吸收，因此尿液中尿素浓度较高。", mastered: false, collected: false },
  { id: "bio-7b-jn-011", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列结构中，属于视觉感受器的是（　　）", options: ["A. 角膜", "B. 晶状体", "C. 视网膜", "D. 玻璃体"], answer: "C", analysis: "视网膜上有感光细胞，能感受光刺激，是视觉感受器。角膜和晶状体有折光作用，玻璃体也有折光作用并支撑眼球。", mastered: false, collected: false },
  { id: "bio-7b-jn-012", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列关于近视的叙述，正确的是（　　）", options: ["A. 物像落在视网膜前方", "B. 物像落在视网膜后方", "C. 晶状体曲度过小", "D. 眼球前后径过短"], answer: "A", analysis: "近视是由于晶状体曲度过大或眼球前后径过长，使远处物体的物像落在视网膜前方，看不清远处物体，可配戴凹透镜矫正。", mastered: false, collected: false },
  { id: "bio-7b-jn-013", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列反射活动中，与「望梅止渴」属于同一类型的是（　　）", options: ["A. 缩手反射", "B. 膝跳反射", "C. 谈梅生津", "D. 眨眼反射"], answer: "C", analysis: "「望梅止渴」和「谈梅生津」都是后天形成的复杂反射，与语言文字有关，神经中枢在大脑皮层。缩手反射、膝跳反射、眨眼反射是简单反射。", mastered: false, collected: false },
  { id: "bio-7b-jn-014", subject: "biology", grade: "七年级下册", version: "济南版", type: "single", stem: "下列内分泌腺中，能分泌多种激素的是（　　）", options: ["A. 甲状腺", "B. 垂体", "C. 胰岛", "D. 肾上腺"], answer: "B", analysis: "垂体能分泌生长激素、促甲状腺激素、促性腺激素等多种激素，是人体最重要的内分泌腺，调节其他内分泌腺的活动。", mastered: false, collected: false },
  { id: "bio-7b-jn-015", subject: "biology", grade: "七年级下册", version: "济南版", type: "judge", stem: "近视眼可以配戴凸透镜矫正。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "近视眼由于物像落在视网膜前方，应配戴凹透镜矫正，使光线发散后再会聚到视网膜上。远视眼才配戴凸透镜矫正。", mastered: false, collected: false },

  // ===== 生物 冀少版 =====
  { id: "bio-7b-js-001", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列食物中含蛋白质最丰富的是（　　）", options: ["A. 大米", "B. 黄豆", "C. 白菜", "D. 红薯"], answer: "B", analysis: "黄豆富含蛋白质，是植物性蛋白质的重要来源。大米、红薯主要含糖类，白菜主要含维生素和无机盐。", mastered: false, collected: false },
  { id: "bio-7b-js-002", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于三大产热营养素的叙述，正确的是（　　）", options: ["A. 糖类是构成细胞的基本物质", "B. 脂肪是主要的供能物质", "C. 蛋白质是主要的储能物质", "D. 糖类是主要的供能物质"], answer: "D", analysis: "三大产热营养素中，糖类是主要的供能物质，脂肪是主要的储能物质，蛋白质是构成细胞的基本物质，也能供能。", mastered: false, collected: false },
  { id: "bio-7b-js-003", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列现象中，属于物理性消化的是（　　）", options: ["A. 唾液消化淀粉", "B. 胃液消化蛋白质", "C. 牙齿咀嚼食物", "D. 肠液消化脂肪"], answer: "C", analysis: "物理性消化是通过牙齿的咀嚼、舌的搅拌、胃肠蠕动等改变食物形状和大小的过程，不改变食物分子结构。化学性消化需要消化酶参与。", mastered: false, collected: false },
  { id: "bio-7b-js-004", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列消化液中，含有多种消化酶的是（　　）", options: ["A. 唾液", "B. 胃液", "C. 胆汁", "D. 肠液"], answer: "D", analysis: "肠液中含有多种消化酶，能消化糖类、蛋白质、脂肪。唾液只有唾液淀粉酶，胃液只有胃蛋白酶，胆汁不含消化酶。", mastered: false, collected: false },
  { id: "bio-7b-js-005", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于呼吸道的叙述，正确的是（　　）", options: ["A. 呼吸道是气体交换的场所", "B. 呼吸道能对吸入气体进行处理", "C. 呼吸道只有通气功能", "D. 呼吸道与发声无关"], answer: "B", analysis: "呼吸道能对吸入气体进行处理，使气体温暖、湿润、清洁。喉部有声带，是发声器官。气体交换在肺泡完成。", mastered: false, collected: false },
  { id: "bio-7b-js-006", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列结构中，是发声器官的是（　　）", options: ["A. 鼻", "B. 咽", "C. 喉", "D. 气管"], answer: "C", analysis: "喉是呼吸的通道，也是发声器官。喉腔侧壁有声带，气流通过时振动声带而发声。", mastered: false, collected: false },
  { id: "bio-7b-js-007", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于血液的叙述，正确的是（　　）", options: ["A. 血浆能运输氧气", "B. 红细胞能运输养料", "C. 血浆呈淡黄色半透明", "D. 血液是红色是因为含血浆"], answer: "C", analysis: "血浆呈淡黄色半透明状，主要功能是运载血细胞、运输养料和废物。红细胞运输氧气，血液红色是因为红细胞中含血红蛋白。", mastered: false, collected: false },
  { id: "bio-7b-js-008", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于心率的叙述，正确的是（　　）", options: ["A. 心率是指每秒心脏跳动的次数", "B. 成年人正常心率约为75次/分", "C. 心率越低越健康", "D. 心率与年龄无关"], answer: "B", analysis: "心率是指心脏每分钟跳动的次数，成年人正常心率约为75次/分，范围60-100次/分。心率与年龄、体质等因素有关。", mastered: false, collected: false },
  { id: "bio-7b-js-009", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于血压的叙述，正确的是（　　）", options: ["A. 血压是指血液对血管壁的侧压力", "B. 收缩压是心室舒张时的血压", "C. 舒张压是心室收缩时的血压", "D. 血压只测动脉"], answer: "A", analysis: "血压是指血液对血管壁的侧压力。收缩压是心室收缩时的血压，舒张压是心室舒张时的血压。一般测量上臂肱动脉处。", mastered: false, collected: false },
  { id: "bio-7b-js-010", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于肾单位的叙述，正确的是（　　）", options: ["A. 每个肾脏只有一个肾单位", "B. 肾单位是肾脏的基本单位", "C. 肾单位不包括肾小球", "D. 肾单位与尿液形成无关"], answer: "B", analysis: "肾单位是肾脏结构和功能的基本单位，每个肾脏约有100万个肾单位，由肾小球、肾小囊和肾小管组成。", mastered: false, collected: false },
  { id: "bio-7b-js-011", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于排尿的叙述，正确的是（　　）", options: ["A. 排尿是简单反射", "B. 排尿是复杂反射", "C. 排尿只受脊髓控制", "D. 排尿不受大脑控制"], answer: "A", analysis: "排尿反射是简单反射，神经中枢在脊髓。但排尿也受大脑皮层控制，成人可以有意识地控制排尿。", mastered: false, collected: false },
  { id: "bio-7b-js-012", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列关于视觉形成的叙述，正确的是（　　）", options: ["A. 视觉在角膜形成", "B. 视觉在晶状体形成", "C. 视觉在大脑皮层视觉中枢形成", "D. 视觉在视网膜形成"], answer: "C", analysis: "视网膜接受光刺激产生神经冲动，神经冲动经视神经传到大脑皮层的视觉中枢，形成视觉。", mastered: false, collected: false },
  { id: "bio-7b-js-013", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列结构中，属于效应器的是（　　）", options: ["A. 感受器", "B. 传入神经", "C. 神经中枢", "D. 传出神经末梢及其支配的肌肉或腺体"], answer: "D", analysis: "效应器是指传出神经末梢及其支配的肌肉或腺体。反射弧包括感受器、传入神经、神经中枢、传出神经、效应器。", mastered: false, collected: false },
  { id: "bio-7b-js-014", subject: "biology", grade: "七年级下册", version: "冀少版", type: "single", stem: "下列激素中，幼年分泌过少会引起侏儒症的是（　　）", options: ["A. 甲状腺激素", "B. 生长激素", "C. 胰岛素", "D. 性激素"], answer: "B", analysis: "幼年时期生长激素分泌过少会引起侏儒症，表现为身材矮小但智力正常。幼年甲状腺激素分泌过少会引起呆小症。", mastered: false, collected: false },
  { id: "bio-7b-js-015", subject: "biology", grade: "七年级下册", version: "冀少版", type: "judge", stem: "肾小管能重吸收全部葡萄糖。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "原尿流经肾小管时，全部葡萄糖被重吸收回血液，因此正常尿液中不含葡萄糖。如果尿液中有葡萄糖，可能是胰岛功能异常。", mastered: false, collected: false },

  // ===== 生物 北京版 =====
  { id: "bio-7b-bj-001", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列物质中，被称为「第七类营养素」的是（　　）", options: ["A. 维生素", "B. 无机盐", "C. 膳食纤维", "D. 水"], answer: "C", analysis: "膳食纤维被称为「第七类营养素」，能促进胃肠蠕动，有利于排便，对人体健康有重要作用，主要存在于蔬菜、水果、粗粮中。", mastered: false, collected: false },
  { id: "bio-7b-bj-002", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于青少年膳食的叙述，正确的是（　　）", options: ["A. 多吃肉类，少吃蔬菜", "B. 只吃蔬菜水果", "C. 荤素搭配，粗细搭配", "D. 多吃零食补充营养"], answer: "C", analysis: "青少年生长发育快，需要全面营养。应做到荤素搭配、粗细搭配，多吃蔬菜水果，少吃零食，保证营养均衡。", mastered: false, collected: false },
  { id: "bio-7b-bj-003", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列器官中，能分泌消化液进入小肠的是（　　）", options: ["A. 唾液腺", "B. 胃腺", "C. 肝脏和胰腺", "D. 大肠腺"], answer: "C", analysis: "肝脏分泌胆汁，胰腺分泌胰液，都通过导管进入小肠。唾液腺分泌唾液进入口腔，胃腺分泌胃液进入胃。", mastered: false, collected: false },
  { id: "bio-7b-bj-004", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于消化道内消化酶的叙述，正确的是（　　）", options: ["A. 口腔中有胃蛋白酶", "B. 胃中有唾液淀粉酶", "C. 小肠中有多种消化酶", "D. 大肠中有消化酶"], answer: "C", analysis: "小肠中有肠液，含多种消化酶，能消化糖类、蛋白质和脂肪。口腔中有唾液淀粉酶，胃中有胃蛋白酶，大肠不分泌消化酶。", mastered: false, collected: false },
  { id: "bio-7b-bj-005", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于气体交换的叙述，正确的是（　　）", options: ["A. 肺泡内氧气进入血液", "B. 血液中氧气进入肺泡", "C. 组织细胞产生二氧化碳进入血液", "D. 肺泡内二氧化碳进入血液"], answer: "A", analysis: "肺泡内的气体交换：肺泡内氧气进入血液，血液中二氧化碳进入肺泡。组织里的气体交换：血液中氧气进入组织细胞，组织细胞产生的二氧化碳进入血液。", mastered: false, collected: false },
  { id: "bio-7b-bj-006", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列血液中，含氧量最高的是（　　）", options: ["A. 肺动脉内的血", "B. 肺静脉内的血", "C. 上腔静脉内的血", "D. 下腔静脉内的血"], answer: "B", analysis: "肺静脉内的血是经过肺泡气体交换后的动脉血，含氧丰富。肺动脉、上下腔静脉内的血都是静脉血，含氧较少。", mastered: false, collected: false },
  { id: "bio-7b-bj-007", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于心脏瓣膜的叙述，正确的是（　　）", options: ["A. 房室瓣防止血液从心室倒流回心房", "B. 动脉瓣防止血液从心房倒流回心室", "C. 房室瓣位于心室和动脉之间", "D. 动脉瓣位于心房和心室之间"], answer: "A", analysis: "房室瓣位于心房和心室之间，防止血液从心室倒流回心房。动脉瓣位于心室和动脉之间，防止血液从动脉倒流回心室。", mastered: false, collected: false },
  { id: "bio-7b-bj-008", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于血型的叙述，正确的是（　　）", options: ["A. A型血红细胞上有B凝集原", "B. B型血红细胞上有A凝集原", "C. AB型血红细胞上同时有A和B凝集原", "D. O型血红细胞上有A凝集原"], answer: "C", analysis: "A型血红细胞上有A凝集原，B型血红细胞上有B凝集原，AB型血同时有A和B凝集原，O型血两种凝集原都没有。", mastered: false, collected: false },
  { id: "bio-7b-bj-009", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于尿液形成的叙述，正确的是（　　）", options: ["A. 肾小球有重吸收功能", "B. 肾小囊有滤过功能", "C. 肾小管有滤过功能", "D. 肾小球有滤过作用"], answer: "D", analysis: "尿液形成包括滤过和重吸收两个过程。肾小球有滤过作用，形成原尿；肾小管有重吸收作用，形成尿液。", mastered: false, collected: false },
  { id: "bio-7b-bj-010", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列液体中，含大分子蛋白质最多的是（　　）", options: ["A. 血浆", "B. 原尿", "C. 尿液", "D. 组织液"], answer: "A", analysis: "血浆中含有大分子蛋白质。原尿和血浆相比不含大分子蛋白质，因为蛋白质不能通过肾小球滤过。尿液中也不含蛋白质。", mastered: false, collected: false },
  { id: "bio-7b-bj-011", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列关于耳听觉形成的叙述，正确的是（　　）", options: ["A. 听觉在鼓膜形成", "B. 听觉在听小骨形成", "C. 听觉在耳蜗形成", "D. 听觉在大脑皮层听觉中枢形成"], answer: "D", analysis: "声波经外耳道传到鼓膜引起振动，经听小骨传到耳蜗，耳蜗内听觉感受器产生神经冲动，经听觉神经传到大脑皮层听觉中枢形成听觉。", mastered: false, collected: false },
  { id: "bio-7b-bj-012", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列反射中，与人类语言有关的是（　　）", options: ["A. 缩手反射", "B. 膝跳反射", "C. 望文生义", "D. 眨眼反射"], answer: "C", analysis: "望文生义是与人类语言文字有关的复杂反射，神经中枢在大脑皮层。缩手反射、膝跳反射、眨眼反射都是简单反射。", mastered: false, collected: false },
  { id: "bio-7b-bj-013", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列内分泌腺中，能分泌胰岛素的是（　　）", options: ["A. 甲状腺", "B. 胰岛", "C. 垂体", "D. 肾上腺"], answer: "B", analysis: "胰岛位于胰腺内，能分泌胰岛素，胰岛素能调节糖代谢，降低血糖浓度。甲状腺分泌甲状腺激素，垂体分泌生长激素。", mastered: false, collected: false },
  { id: "bio-7b-bj-014", subject: "biology", grade: "七年级下册", version: "北京版", type: "single", stem: "下列现象中，与激素调节无关的是（　　）", options: ["A. 血糖浓度维持稳定", "B. 人体生长发育", "C. 青春期第二性征出现", "D. 缩手反射"], answer: "D", analysis: "缩手反射是神经调节，与激素调节无关。血糖稳定与胰岛素有关，生长发育与生长激素有关，第二性征与性激素有关。", mastered: false, collected: false },
  { id: "bio-7b-bj-015", subject: "biology", grade: "七年级下册", version: "北京版", type: "judge", stem: "人体生命活动主要受神经系统的调节，但也受激素调节的影响。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "人体生命活动的调节包括神经调节和激素调节，其中神经调节起主导作用，激素调节也有重要影响，两者相互配合。", mastered: false, collected: false },

  // ===== 生物 鲁科版（五四学制）=====
  { id: "bio-7b-lk-001", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列食物中，富含脂肪的是（　　）", options: ["A. 米饭", "B. 馒头", "C. 瘦肉", "D. 花生"], answer: "D", analysis: "花生富含脂肪。米饭、馒头主要含糖类；瘦肉主要含蛋白质。脂肪是人体内主要的储能物质。", mastered: false, collected: false },
  { id: "bio-7b-lk-002", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于水在人体内作用的叙述，正确的是（　　）", options: ["A. 水能提供能量", "B. 水是构成细胞的主要成分", "C. 水能运输营养物质和废物", "D. 水参与调节体温无关"], answer: "C", analysis: "水是人体内物质运输的主要介质，能运输营养物质和废物，也参与体温调节。但水既不提供能量，也不构成细胞的主要成分。", mastered: false, collected: false },
  { id: "bio-7b-lk-003", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列消化液中，能将淀粉彻底分解为葡萄糖的是（　　）", options: ["A. 唾液", "B. 胃液", "C. 胆汁", "D. 肠液"], answer: "D", analysis: "肠液中含有多种消化酶，能将淀粉彻底分解为葡萄糖。唾液只能将淀粉分解为麦芽糖，胃液消化蛋白质，胆汁不含消化酶。", mastered: false, collected: false },
  { id: "bio-7b-lk-004", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于唾液淀粉酶实验的叙述，正确的是（　　）", options: ["A. 实验要在37℃条件下进行", "B. 唾液淀粉酶将淀粉分解为葡萄糖", "C. 滴加碘液后变蓝说明淀粉已被分解", "D. 实验无需对照"], answer: "A", analysis: "唾液淀粉酶的最适温度是37℃，与人体体温相近。唾液淀粉酶将淀粉分解为麦芽糖。滴加碘液后不变蓝说明淀粉已被分解。", mastered: false, collected: false },
  { id: "bio-7b-lk-005", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于肺泡适于气体交换特点的叙述，错误的是（　　）", options: ["A. 肺泡数目多，总面积大", "B. 肺泡壁很薄，仅一层上皮细胞", "C. 肺泡外缠绕着毛细血管", "D. 肺泡外有弹性纤维，能分泌消化酶"], answer: "D", analysis: "肺泡外有弹性纤维有助于肺泡的弹性回缩，但肺泡不分泌消化酶。肺泡数目多、壁薄、外缠毛细血管都是适于气体交换的特点。", mastered: false, collected: false },
  { id: "bio-7b-lk-006", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于平静呼吸的叙述，正确的是（　　）", options: ["A. 吸气是主动的，呼气是被动的", "B. 呼气是主动的，吸气是被动的", "C. 吸气和呼气都是主动的", "D. 吸气和呼气都是被动的"], answer: "A", analysis: "平静呼吸时，吸气是主动的（膈肌和肋间肌收缩），呼气是被动的（膈肌和肋间肌舒张，依靠肺的弹性回缩）。", mastered: false, collected: false },
  { id: "bio-7b-lk-007", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于血液循环的叙述，正确的是（　　）", options: ["A. 体循环将动脉血变为静脉血", "B. 体循环将静脉血变为动脉血", "C. 肺循环将动脉血变为动脉血", "D. 体循环中血液含氧量增加"], answer: "A", analysis: "体循环中，血液流经全身毛细血管时，氧气进入组织细胞，组织细胞产生的二氧化碳进入血液，动脉血变为静脉血。", mastered: false, collected: false },
  { id: "bio-7b-lk-008", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列血管中，管腔内有静脉瓣的是（　　）", options: ["A. 动脉", "B. 静脉", "C. 毛细血管", "D. 心脏"], answer: "B", analysis: "静脉内有静脉瓣，能防止血液倒流，特别是在四肢的静脉中。动脉和心脏内有动脉瓣和房室瓣。毛细血管没有瓣膜。", mastered: false, collected: false },
  { id: "bio-7b-lk-009", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于输血的叙述，正确的是（　　）", options: ["A. 一次献血200-400毫升不影响健康", "B. 献血后不能恢复", "C. 健康成年人一次可献血1000毫升", "D. 献血会损害健康"], answer: "A", analysis: "健康成年人一次献血200-400毫升不影响健康，献血后身体能很快恢复。献血是高尚行为，能挽救他人生命。", mastered: false, collected: false },
  { id: "bio-7b-lk-010", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于尿液成分的叙述，正确的是（　　）", options: ["A. 尿液中含有葡萄糖", "B. 尿液中含有大分子蛋白质", "C. 尿液中含有水和尿素", "D. 尿液中含有血细胞"], answer: "C", analysis: "正常尿液中主要含有水、尿素、无机盐等，不含葡萄糖、大分子蛋白质和血细胞。如果尿液中含有这些物质，可能是肾脏病变。", mastered: false, collected: false },
  { id: "bio-7b-lk-011", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于近视成因的叙述，正确的是（　　）", options: ["A. 晶状体曲度过小", "B. 眼球前后径过短", "C. 物像落在视网膜前方", "D. 物像落在视网膜后方"], answer: "C", analysis: "近视是由于晶状体曲度过大或眼球前后径过长，使远处物像落在视网膜前方，看不清远处物体。可配戴凹透镜矫正。", mastered: false, collected: false },
  { id: "bio-7b-lk-012", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于人体反射的叙述，正确的是（　　）", options: ["A. 简单反射是后天形成的", "B. 复杂反射是先天就有的", "C. 「一朝被蛇咬，十年怕井绳」是复杂反射", "D. 缩手反射是复杂反射"], answer: "C", analysis: "「一朝被蛇咬，十年怕井绳」是后天形成的复杂反射，神经中枢在大脑皮层。简单反射是先天就有的，缩手反射是简单反射。", mastered: false, collected: false },
  { id: "bio-7b-lk-013", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于垂体的叙述，正确的是（　　）", options: ["A. 垂体是人体最大的内分泌腺", "B. 垂体只分泌生长激素", "C. 垂体能调节其他内分泌腺的活动", "D. 垂体位于胸腔内"], answer: "C", analysis: "垂体是人体最重要的内分泌腺，能分泌多种激素，包括生长激素和多种促激素，调节其他内分泌腺的活动。垂体位于大脑下方。", mastered: false, collected: false },
  { id: "bio-7b-lk-014", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "single", stem: "下列关于人类活动对生物圈影响的叙述，正确的是（　　）", options: ["A. 乱砍滥伐不会影响生态平衡", "B. 工业排放不会污染环境", "C. 引进外来物种不会影响本地生态", "D. 植树造林能改善生态环境"], answer: "D", analysis: "植树造林能改善生态环境，防止水土流失，调节气候。乱砍滥伐会破坏生态平衡，工业排放会污染环境，引进外来物种可能危害本地生态。", mastered: false, collected: false },
  { id: "bio-7b-lk-015", subject: "biology", grade: "七年级下册", version: "鲁科版（五四学制）", type: "judge", stem: "动脉里流动脉血，静脉里流静脉血。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "动脉血和静脉血是根据含氧量来区分的，与血管类型无关。肺动脉里流静脉血，肺静脉里流动脉血。所以「动脉里流动脉血」是错误的。", mastered: false, collected: false },

  // ===== 历史 统编版 =====
  { id: "his-7b-tb-001", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "隋朝建立的时间是（　　）", options: ["A. 581年", "B. 589年", "C. 618年", "D. 605年"], answer: "A", analysis: "581年，杨坚建立隋朝，定都长安，杨坚就是隋文帝。589年隋灭陈，统一全国。618年隋朝灭亡。", mastered: false, collected: false },
  { id: "his-7b-tb-002", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "隋朝大运河的中心是（　　）", options: ["A. 长安", "B. 洛阳", "C. 涿郡", "D. 余杭"], answer: "B", analysis: "隋朝大运河以洛阳为中心，北达涿郡（今北京），南至余杭（今杭州），全长2000多千米，是古代世界上最长的运河。", mastered: false, collected: false },
  { id: "his-7b-tb-003", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "开创科举制的朝代是（　　）", options: ["A. 隋朝", "B. 唐朝", "C. 宋朝", "D. 明朝"], answer: "A", analysis: "隋炀帝时期开设进士科，标志着科举制正式确立。科举制在唐朝得到完善，宋明清各朝沿用，直到1905年废除。", mastered: false, collected: false },
  { id: "his-7b-tb-004", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "唐朝的建立者是（　　）", options: ["A. 李渊", "B. 李世民", "C. 杨坚", "D. 武则天"], answer: "A", analysis: "618年，李渊在长安称帝，建立唐朝，李渊就是唐高祖。李世民是唐太宗，通过玄武门之变继位。", mastered: false, collected: false },
  { id: "his-7b-tb-005", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "「贞观之治」时期的皇帝是（　　）", options: ["A. 唐高祖", "B. 唐太宗", "C. 唐玄宗", "D. 唐高宗"], answer: "B", analysis: "唐太宗李世民在位期间，年号贞观，政治清明，经济恢复发展，国力增强，史称「贞观之治」。", mastered: false, collected: false },
  { id: "his-7b-tb-006", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "中国历史上唯一的女皇帝是（　　）", options: ["A. 吕后", "B. 慈禧太后", "C. 武则天", "D. 王政君"], answer: "C", analysis: "武则天是中国历史上唯一的女皇帝，她改国号为周，在位期间社会经济继续发展，史称「政启开元，治宏贞观」。", mastered: false, collected: false },
  { id: "his-7b-tb-007", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "唐朝进入鼎盛时期的标志是（　　）", options: ["A. 贞观之治", "B. 开元盛世", "C. 文景之治", "D. 光武中兴"], answer: "B", analysis: "唐玄宗统治前期，年号开元，政治稳定，经济繁荣，国库充盈，唐朝进入鼎盛时期，史称「开元盛世」。", mastered: false, collected: false },
  { id: "his-7b-tb-008", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "发明活字印刷术的是（　　）", options: ["A. 蔡伦", "B. 毕昇", "C. 祖冲之", "D. 沈括"], answer: "B", analysis: "北宋平民毕昇发明了活字印刷术，比欧洲早约400年，是印刷史上一大变革。蔡伦改进造纸术，祖冲之是数学家，沈括是北宋科学家。", mastered: false, collected: false },
  { id: "his-7b-tb-009", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "北宋的建立者是（　　）", options: ["A. 赵匡胤", "B. 赵光义", "C. 赵构", "D. 耶律阿保机"], answer: "A", analysis: "960年，后周大将赵匡胤在陈桥驿发动兵变，建立宋朝，定都东京（今开封），史称北宋。赵匡胤就是宋太祖。", mastered: false, collected: false },
  { id: "his-7b-tb-010", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "元朝的建立者是（　　）", options: ["A. 铁木真", "B. 窝阔台", "C. 忽必烈", "D. 蒙哥"], answer: "C", analysis: "1271年，忽必烈改国号为元，1272年定都大都（今北京）。1279年元灭南宋，统一全国。铁木真是成吉思汗，统一蒙古各部。", mastered: false, collected: false },
  { id: "his-7b-tb-011", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "明朝的建立者是（　　）", options: ["A. 朱元璋", "B. 朱棣", "C. 朱由检", "D. 赵匡胤"], answer: "A", analysis: "1368年，朱元璋在应天称帝，建立明朝，年号洪武，朱元璋就是明太祖。同年明军攻占大都，元朝灭亡。", mastered: false, collected: false },
  { id: "his-7b-tb-012", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "郑和下西洋的朝代是（　　）", options: ["A. 唐朝", "B. 宋朝", "C. 元朝", "D. 明朝"], answer: "D", analysis: "明成祖朱棣时期，郑和率船队七下西洋，从1405年到1433年，先后到达亚非30多个国家和地区，最远到达红海和非洲东海岸。", mastered: false, collected: false },
  { id: "his-7b-tb-013", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "清朝设置驻藏大臣的时间是（　　）", options: ["A. 1727年", "B. 1684年", "C. 1644年", "D. 1793年"], answer: "A", analysis: "1727年，清朝设置驻藏大臣，代表中央政府与达赖、班禅共同管理西藏事务，加强了中央对西藏的管辖。", mastered: false, collected: false },
  { id: "his-7b-tb-014", subject: "history", grade: "七年级下册", version: "统编版", type: "single", stem: "下列人物中，抗击荷兰殖民者收复台湾的是（　　）", options: ["A. 戚继光", "B. 郑成功", "C. 岳飞", "D. 文天祥"], answer: "B", analysis: "1662年，郑成功驱逐荷兰殖民者，收复台湾。戚继光抗击倭寇，岳飞抗金，文天祥抗元。", mastered: false, collected: false },
  { id: "his-7b-tb-015", subject: "history", grade: "七年级下册", version: "统编版", type: "judge", stem: "科举制在清朝末年被废除。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "1905年，清政府废除科举制，延续了1300多年的科举制度正式终结，这是中国教育史上的重大变革。", mastered: false, collected: false },

  // ===== 历史 统编版（2024）=====
  { id: "his-7b-tb24-001", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "隋朝统一全国的时间是（　　）", options: ["A. 581年", "B. 589年", "C. 618年", "D. 605年"], answer: "B", analysis: "589年，隋灭陈，结束了长期分裂局面，统一全国。581年是隋朝建立时间，618年是隋朝灭亡时间。", mastered: false, collected: false },
  { id: "his-7b-tb24-002", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "隋朝大运河开通的皇帝是（　　）", options: ["A. 隋文帝", "B. 隋炀帝", "C. 唐太宗", "D. 唐玄宗"], answer: "B", analysis: "605年开始，隋炀帝征发数百万人开通大运河，大运河以洛阳为中心，北达涿郡，南至余杭，加强了南北经济交流。", mastered: false, collected: false },
  { id: "his-7b-tb24-003", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "唐朝完善科举制的关键人物是（　　）", options: ["A. 隋文帝", "B. 隋炀帝", "C. 唐太宗", "D. 武则天"], answer: "C", analysis: "唐太宗时期增加考试科目，进士科成为最重要的科目，武则天首创武举和殿试，唐玄宗时诗赋成为进士科主要内容，科举制进一步完善。", mastered: false, collected: false },
  { id: "his-7b-tb24-004", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "「水能载舟，亦能覆舟」是哪位皇帝常引用的话（　　）", options: ["A. 隋文帝", "B. 唐太宗", "C. 唐玄宗", "D. 宋太祖"], answer: "B", analysis: "唐太宗李世民常引用荀子「水能载舟，亦能覆舟」的话，说明他认识到人民群众的力量，重视民意，勤于政事。", mastered: false, collected: false },
  { id: "his-7b-tb24-005", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "唐代著名的谏臣是（　　）", options: ["A. 房玄龄", "B. 杜如晦", "C. 魏征", "D. 姚崇"], answer: "C", analysis: "魏征是唐太宗时期著名的谏臣，敢于直言进谏，先后进谏200多次，唐太宗把他比作「镜」以正己过。", mastered: false, collected: false },
  { id: "his-7b-tb24-006", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "唐朝时被尊为「天可汗」的是（　　）", options: ["A. 唐高祖", "B. 唐太宗", "C. 唐玄宗", "D. 唐高宗"], answer: "B", analysis: "唐太宗实行开明的民族政策，被西北各族首领尊为「天可汗」，反映了唐朝民族关系的融洽。", mastered: false, collected: false },
  { id: "his-7b-tb24-007", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "文成公主入藏嫁给松赞干布发生在（　　）", options: ["A. 唐太宗时期", "B. 唐高宗时期", "C. 唐玄宗时期", "D. 武则天时期"], answer: "A", analysis: "唐太宗时期，吐蕃赞普松赞干布多次请求和亲，641年文成公主入藏，促进了唐蕃经济文化交流和汉藏友谊。", mastered: false, collected: false },
  { id: "his-7b-tb24-008", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "唐朝灭亡的时间是（　　）", options: ["A. 755年", "B. 907年", "C. 960年", "D. 618年"], answer: "B", analysis: "907年，朱温篡唐，唐朝灭亡，中国进入五代十国时期。755年是安史之乱爆发，960年是北宋建立。", mastered: false, collected: false },
  { id: "his-7b-tb24-009", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "北宋削弱地方权力的措施是（　　）", options: ["A. 分封制", "B. 郡县制", "C. 杯酒释兵权", "D. 行省制"], answer: "C", analysis: "宋太祖赵匡胤通过「杯酒释兵权」解除大将兵权，加强中央集权，防止武将专权，这是北宋加强中央集权的重要措施。", mastered: false, collected: false },
  { id: "his-7b-tb24-010", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "辽、宋、夏并立时期，契丹族建立的政权是（　　）", options: ["A. 辽", "B. 西夏", "C. 金", "D. 元"], answer: "A", analysis: "916年，契丹族首领耶律阿保机建立契丹国，后改称辽。西夏是党项族建立的政权，金是女真族建立的政权。", mastered: false, collected: false },
  { id: "his-7b-tb24-011", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "岳飞抗击的政权是（　　）", options: ["A. 辽", "B. 西夏", "C. 金", "D. 元"], answer: "C", analysis: "岳飞是南宋抗金名将，率岳家军在郾城大败金军。后被秦桧以「莫须有」罪名杀害。岳飞抗金是民族英雄。", mastered: false, collected: false },
  { id: "his-7b-tb24-012", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "元朝在地方实行的行政制度是（　　）", options: ["A. 分封制", "B. 郡县制", "C. 州县制", "D. 行省制"], answer: "D", analysis: "元朝在地方实行行省制度，将全国分为10个行省，行省下设路、府、州、县。行省制对后世影响深远，我国省级行政区划源于此。", mastered: false, collected: false },
  { id: "his-7b-tb24-013", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "元朝管理西藏的机构是（　　）", options: ["A. 宣政院", "B. 驻藏大臣", "C. 理藩院", "D. 西域都护"], answer: "A", analysis: "元朝设宣政院管理西藏地区事务，西藏正式成为元朝的行政区域。驻藏大臣是清朝设置的，理藩院也是清朝机构。", mastered: false, collected: false },
  { id: "his-7b-tb24-014", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "明太祖加强皇权的措施是（　　）", options: ["A. 废除丞相", "B. 设立锦衣卫", "C. 设立东厂", "D. 设立军机处"], answer: "A", analysis: "明太祖朱元璋废除丞相，六部直接对皇帝负责，加强了皇权。锦衣卫也是明太祖设立，东厂是明成祖设立，军机处是清朝设立。", mastered: false, collected: false },
  { id: "his-7b-tb24-015", subject: "history", grade: "七年级下册", version: "统编版（2024）", type: "judge", stem: "明朝废除丞相后，六部直接对皇帝负责。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "明太祖废除丞相，六部直接对皇帝负责，皇权大大加强。这是明朝加强君主专制的重要措施。", mastered: false, collected: false },

  // ===== 历史 统编版（五四学制）=====
  { id: "his-7b-tb54-001", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "隋朝大运河的最北端是（　　）", options: ["A. 涿郡", "B. 余杭", "C. 洛阳", "D. 长安"], answer: "A", analysis: "隋朝大运河以洛阳为中心，北达涿郡（今北京），南至余杭（今杭州），沟通了海河、黄河、淮河、长江、钱塘江五大水系。", mastered: false, collected: false },
  { id: "his-7b-tb54-002", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "隋朝灭亡的原因是（　　）", options: ["A. 外族入侵", "B. 隋炀帝暴政", "C. 自然灾害", "D. 农民起义"], answer: "B", analysis: "隋炀帝统治后期，暴政无道，营建东都、开凿运河、三征高句丽，劳民伤财，引发隋末农民起义，618年隋朝灭亡。", mastered: false, collected: false },
  { id: "his-7b-tb54-003", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "唐太宗「纳谏」的代表人物是（　　）", options: ["A. 房玄龄", "B. 杜如晦", "C. 魏征", "D. 长孙无忌"], answer: "C", analysis: "魏征是唐太宗时期著名的谏臣，敢于直言进谏，先后进谏200多次，被唐太宗称为「镜」。", mastered: false, collected: false },
  { id: "his-7b-tb54-004", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "「开元盛世」的皇帝是（　　）", options: ["A. 唐太宗", "B. 唐高宗", "C. 武则天", "D. 唐玄宗"], answer: "D", analysis: "唐玄宗李隆基统治前期，年号开元，政治稳定，经济繁荣，文化昌盛，国力达到鼎盛，史称「开元盛世」。", mastered: false, collected: false },
  { id: "his-7b-tb54-005", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "唐朝由盛转衰的转折点是（　　）", options: ["A. 安史之乱", "B. 藩镇割据", "C. 黄巢起义", "D. 朱温篡唐"], answer: "A", analysis: "755-763年的安史之乱是唐朝由盛转衰的转折点。安史之乱后，唐朝中央集权削弱，形成藩镇割据局面。", mastered: false, collected: false },
  { id: "his-7b-tb54-006", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "唐朝时期中日交流的重要人物是（　　）", options: ["A. 鉴真", "B. 玄奘", "C. 郑和", "D. 张骞"], answer: "A", analysis: "鉴真六次东渡日本，传授佛经和唐朝文化，对中日文化交流做出了重要贡献。玄奘西行天竺，郑和下西洋是明朝，张骞出使西域是汉朝。", mastered: false, collected: false },
  { id: "his-7b-tb54-007", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "唐朝时期中印交流的代表人物是（　　）", options: ["A. 鉴真", "B. 玄奘", "C. 郑和", "D. 班超"], answer: "B", analysis: "玄奘西行天竺（古印度）取经，历时17年，带回大量佛经，写成《大唐西域记》，是中印文化交流的使者。", mastered: false, collected: false },
  { id: "his-7b-tb54-008", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "北宋的经济特点是（　　）", options: ["A. 商业繁荣", "B. 农业落后", "C. 手工业衰退", "D. 海外贸易衰落"], answer: "A", analysis: "北宋时期商业繁荣，出现了世界上最早的纸币「交子」，城市商业活动打破坊市界限，海外贸易发达，市舶司管理海外贸易。", mastered: false, collected: false },
  { id: "his-7b-tb54-009", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "世界上最早的纸币出现在（　　）", options: ["A. 唐朝", "B. 北宋", "C. 南宋", "D. 元朝"], answer: "B", analysis: "北宋前期，四川地区出现「交子」，是世界上最早的纸币，比欧洲早600多年，反映了北宋商品经济的发达。", mastered: false, collected: false },
  { id: "his-7b-tb54-010", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "南宋的都城是（　　）", options: ["A. 开封", "B. 临安", "C. 建康", "D. 成都"], answer: "B", analysis: "1127年，赵构在临安（今杭州）重建宋朝，史称南宋。开封是北宋都城，南宋与金对峙局面形成。", mastered: false, collected: false },
  { id: "his-7b-tb54-011", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "指南针开始应用于航海是在（　　）", options: ["A. 唐朝", "B. 北宋", "C. 南宋", "D. 元朝"], answer: "B", analysis: "北宋时期，指南针开始应用于航海，大大促进了航海事业的发展，为后来郑和下西洋和新航路开辟创造了条件。", mastered: false, collected: false },
  { id: "his-7b-tb54-012", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "火药开始用于军事是在（　　）", options: ["A. 唐朝末年", "B. 北宋", "C. 南宋", "D. 元朝"], answer: "A", analysis: "唐朝末年，火药开始用于军事。宋元时期火药武器广泛用于战争，火药经阿拉伯人传入欧洲，影响了世界历史进程。", mastered: false, collected: false },
  { id: "his-7b-tb54-013", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "明朝加强特务统治的机构是（　　）", options: ["A. 锦衣卫和东厂", "B. 军机处", "C. 理藩院", "D. 内阁"], answer: "A", analysis: "明太祖设锦衣卫，明成祖设东厂，都是特务机构，由皇帝直接控制，监视官民，加强了君主专制。", mastered: false, collected: false },
  { id: "his-7b-tb54-014", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "清朝雍正帝设立的重要机构是（　　）", options: ["A. 内阁", "B. 锦衣卫", "C. 军机处", "D. 东厂"], answer: "C", analysis: "雍正帝设立军机处，军机大臣跪受笔录，传达皇帝旨意，军国大事由皇帝一人裁决，君主专制达到顶峰。", mastered: false, collected: false },
  { id: "his-7b-tb54-015", subject: "history", grade: "七年级下册", version: "统编版（五四学制）", type: "judge", stem: "清朝军机处的设立标志着君主专制达到顶峰。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "雍正帝设立军机处，军机大臣只是传达皇帝旨意，没有任何决策权，一切军国大事由皇帝一人裁决，君主专制达到顶峰。", mastered: false, collected: false },

  // ===== 地理 人教版 =====
  { id: "geo-7b-rj-001", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "亚洲的地势特点是（　　）", options: ["A. 中部高，四周低", "B. 中部低，四周高", "C. 东高西低", "D. 南高北低"], answer: "A", analysis: "亚洲地势中部高、四周低，中部是青藏高原和帕米尔高原，河流呈放射状向四周分流。", mastered: false, collected: false },
  { id: "geo-7b-rj-002", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "亚洲是世界第几大洲（　　）", options: ["A. 第一大洲", "B. 第二大洲", "C. 第三大洲", "D. 第四大洲"], answer: "A", analysis: "亚洲是世界上面积最大的洲，面积约4400万平方千米，也是跨纬度最广、东西距离最长的大洲。", mastered: false, collected: false },
  { id: "geo-7b-rj-003", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "「世界屋脊」是指（　　）", options: ["A. 青藏高原", "B. 帕米尔高原", "C. 内蒙古高原", "D. 伊朗高原"], answer: "A", analysis: "青藏高原平均海拔4000米以上，是世界最高的高原，被称为「世界屋脊」。", mastered: false, collected: false },
  { id: "geo-7b-rj-004", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "亚洲气候的特点是（　　）", options: ["A. 单一", "B. 复杂多样，季风气候显著", "C. 都是热带气候", "D. 都是温带气候"], answer: "B", analysis: "亚洲面积广大，跨寒、温、热三带，气候复杂多样；由于地处最大大陆东部，面临最大大洋，季风气候显著。", mastered: false, collected: false },
  { id: "geo-7b-rj-005", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "日本的海岸线特点是（　　）", options: ["A. 平直", "B. 曲折", "C. 短", "D. 简单"], answer: "B", analysis: "日本是岛国，海岸线曲折，多优良港湾，有利于渔业、造船业和海上运输的发展。", mastered: false, collected: false },
  { id: "geo-7b-rj-006", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "日本的经济特点是（　　）", options: ["A. 农业发达", "B. 经济对外依赖性强", "C. 资源丰富", "D. 内陆国家"], answer: "B", analysis: "日本地域狭小，资源贫乏，国内市场小，经济对外依赖性强，需进口原料，出口工业产品。", mastered: false, collected: false },
  { id: "geo-7b-rj-007", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "东南亚的地理位置十分重要，因为它位于（　　）", options: ["A. 亚洲和非洲之间", "B. 太平洋和大西洋之间", "C. 亚洲和大洋洲、太平洋和印度洋的「十字路口」", "D. 欧洲和亚洲之间"], answer: "C", analysis: "东南亚位于亚洲和大洋洲、太平洋和印度洋之间的「十字路口」，马六甲海峡是重要的海上通道。", mastered: false, collected: false },
  { id: "geo-7b-rj-008", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "东南亚最重要的粮食作物是（　　）", options: ["A. 小麦", "B. 玉米", "C. 水稻", "D. 高粱"], answer: "C", analysis: "东南亚地处热带，高温多雨，适合水稻生长，水稻是主要的粮食作物，泰国、越南是世界重要的稻米出口国。", mastered: false, collected: false },
  { id: "geo-7b-rj-009", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "印度最主要的气候类型是（　　）", options: ["A. 热带雨林气候", "B. 热带季风气候", "C. 热带沙漠气候", "D. 亚热带季风气候"], answer: "B", analysis: "印度以热带季风气候为主，全年高温，分旱雨两季，季风的不稳定容易造成旱涝灾害。", mastered: false, collected: false },
  { id: "geo-7b-rj-010", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "俄罗斯分布最广的气候类型是（　　）", options: ["A. 温带大陆性气候", "B. 温带季风气候", "C. 极地气候", "D. 温带海洋性气候"], answer: "A", analysis: "俄罗斯面积广大，大部分地区处于高纬度，温带大陆性气候分布最广，冬季漫长寒冷，夏季短促温暖。", mastered: false, collected: false },
  { id: "geo-7b-rj-011", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "中东地区最丰富的矿产资源是（　　）", options: ["A. 煤炭", "B. 铁矿", "C. 石油", "D. 铜矿"], answer: "C", analysis: "中东地区石油资源极其丰富，储量约占世界一半以上，产量和出口量都居世界首位，主要分布在波斯湾及其沿岸地区。", mastered: false, collected: false },
  { id: "geo-7b-rj-012", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "欧洲西部最典型的气候是（　　）", options: ["A. 温带季风气候", "B. 温带海洋性气候", "C. 地中海气候", "D. 温带大陆性气候"], answer: "B", analysis: "欧洲西部以温带海洋性气候为主，全年温和湿润，适合多汁牧草生长，有利于畜牧业发展。", mastered: false, collected: false },
  { id: "geo-7b-rj-013", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "撒哈拉以南非洲最严重的环境问题是（　　）", options: ["A. 酸雨", "B. 土地荒漠化", "C. 海平面上升", "D. 臭氧层破坏"], answer: "B", analysis: "撒哈拉以南非洲由于过度放牧、砍伐森林等，导致土地荒漠化严重，是本地区面临的最主要环境问题之一。", mastered: false, collected: false },
  { id: "geo-7b-rj-014", subject: "geography", grade: "七年级下册", version: "人教版", type: "single", stem: "世界上面积最大的热带雨林分布区是（　　）", options: ["A. 刚果盆地", "B. 亚马孙平原", "C. 东南亚", "D. 澳大利亚"], answer: "B", analysis: "亚马孙平原分布着世界上面积最大的热带雨林，被称为「地球之肺」，通过光合作用提供大量氧气。", mastered: false, collected: false },
  { id: "geo-7b-rj-015", subject: "geography", grade: "七年级下册", version: "人教版", type: "judge", stem: "澳大利亚是世界上唯一独占一块大陆的国家。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "澳大利亚是世界上唯一独占一块大陆的国家，位于南半球，是大洋洲面积最大的国家，首都堪培拉。", mastered: false, collected: false },

  // ===== 地理 人教版（2024）=====
  { id: "geo-7b-rj24-001", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "亚洲与非洲的分界线是（　　）", options: ["A. 苏伊士运河", "B. 巴拿马运河", "C. 乌拉尔山", "D. 土耳其海峡"], answer: "A", analysis: "苏伊士运河是亚洲和非洲的分界线，连接地中海和红海。巴拿马运河是南北美洲分界线，乌拉尔山是亚欧分界线。", mastered: false, collected: false },
  { id: "geo-7b-rj24-002", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "亚洲与北美洲的分界线是（　　）", options: ["A. 苏伊士运河", "B. 白令海峡", "C. 德雷克海峡", "D. 丹麦海峡"], answer: "B", analysis: "白令海峡是亚洲和北美洲的分界线，也是俄罗斯和美国的分界线，沟通北冰洋和太平洋。", mastered: false, collected: false },
  { id: "geo-7b-rj24-003", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "亚洲分布最广的气候类型是（　　）", options: ["A. 温带大陆性气候", "B. 温带季风气候", "C. 热带季风气候", "D. 高原山地气候"], answer: "A", analysis: "亚洲温带大陆性气候分布最广，主要分布在亚洲内陆地区，由于距海远，水汽难以到达，降水少，气温年较差大。", mastered: false, collected: false },
  { id: "geo-7b-rj24-004", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "亚洲东部和南部最显著的气候是（　　）", options: ["A. 温带大陆性气候", "B. 季风气候", "C. 热带雨林气候", "D. 高原山地气候"], answer: "B", analysis: "亚洲东部和南部季风气候显著，包括温带季风气候、亚热带季风气候和热带季风气候，雨热同期有利于农业生产。", mastered: false, collected: false },
  { id: "geo-7b-rj24-005", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "日本多火山地震的原因是（　　）", options: ["A. 位于板块内部", "B. 位于板块交界处", "C. 地形平坦", "D. 气候寒冷"], answer: "B", analysis: "日本位于亚欧板块和太平洋板块交界处，地壳运动活跃，多火山地震，富士山是著名的活火山。", mastered: false, collected: false },
  { id: "geo-7b-rj24-006", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "东南亚由哪两部分组成（　　）", options: ["A. 中南半岛和马来群岛", "B. 印度半岛和阿拉伯半岛", "C. 朝鲜半岛和日本群岛", "D. 中南半岛和菲律宾群岛"], answer: "A", analysis: "东南亚由中南半岛和马来群岛两大部分组成。中南半岛因在中国以南而得名，马来群岛是世界上最大的群岛。", mastered: false, collected: false },
  { id: "geo-7b-rj24-007", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "中南半岛的地形特点是（　　）", options: ["A. 地势平坦", "B. 山河相间，纵列分布", "C. 以平原为主", "D. 以高原为主"], answer: "B", analysis: "中南半岛地形特点是山河相间、纵列分布，大河下游形成冲积平原，是人口和城市的主要分布区。", mastered: false, collected: false },
  { id: "geo-7b-rj24-008", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "印度的人口特点是（　　）", options: ["A. 人口稀少", "B. 人口众多，增长快", "C. 人口负增长", "D. 人口老龄化"], answer: "B", analysis: "印度是世界第二人口大国，人口众多且增长快，给资源和环境带来巨大压力，但也提供丰富的劳动力资源。", mastered: false, collected: false },
  { id: "geo-7b-rj24-009", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "俄罗斯的工业主要分布在（　　）", options: ["A. 亚洲部分", "B. 欧洲部分", "C. 西伯利亚", "D. 远东地区"], answer: "B", analysis: "俄罗斯的工业主要分布在欧洲部分，这里有莫斯科和圣彼得堡等工业区，人口和城市也主要集中在欧洲部分。", mastered: false, collected: false },
  { id: "geo-7b-rj24-010", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "中东地区最匮乏的资源是（　　）", options: ["A. 石油", "B. 天然气", "C. 水资源", "D. 煤炭"], answer: "C", analysis: "中东地区气候干燥，降水稀少，河流湖泊少，水资源极其匮乏，水资源争端是中东地区冲突的重要原因之一。", mastered: false, collected: false },
  { id: "geo-7b-rj24-011", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "欧洲西部的农业以什么为主（　　）", options: ["A. 种植业", "B. 畜牧业", "C. 林业", "D. 渔业"], answer: "B", analysis: "欧洲西部温带海洋性气候广布，全年温和湿润，适合多汁牧草生长，畜牧业发达，被称为「绿色牧场」。", mastered: false, collected: false },
  { id: "geo-7b-rj24-012", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "撒哈拉以南非洲的主要人种是（　　）", options: ["A. 白种人", "B. 黄种人", "C. 黑种人", "D. 混血种人"], answer: "C", analysis: "撒哈拉以南非洲是黑种人的故乡，黑种人占绝大多数，这里也是人类起源地之一。", mastered: false, collected: false },
  { id: "geo-7b-rj24-013", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "澳大利亚特有的动物是（　　）", options: ["A. 老虎", "B. 袋鼠", "C. 狮子", "D. 大象"], answer: "B", analysis: "澳大利亚长期孤立于南半球海洋上，生物进化独特，有许多特有动物，如袋鼠、鸸鹋、鸭嘴兽等，被称为「世界活化石博物馆」。", mastered: false, collected: false },
  { id: "geo-7b-rj24-014", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "single", stem: "美国农业的特点是（　　）", options: ["A. 机械化程度低", "B. 区域专业化", "C. 以小农经济为主", "D. 手工劳动为主"], answer: "B", analysis: "美国农业实现了区域专业化、机械化和高效化，形成多个农业带，如玉米带、小麦带、棉花带等，是世界最大的农产品出口国。", mastered: false, collected: false },
  { id: "geo-7b-rj24-015", subject: "geography", grade: "七年级下册", version: "人教版（2024）", type: "judge", stem: "巴西是世界上热带面积最大的国家。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "巴西大部分领土位于热带，赤道和南回归线穿过，是世界上热带面积最大的国家，热带雨林气候和热带草原气候广布。", mastered: false, collected: false },

  // ===== 地理 湘教版 =====
  { id: "geo-7b-xj-001", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "亚洲地形以什么为主（　　）", options: ["A. 平原", "B. 高原和山地", "C. 盆地", "D. 丘陵"], answer: "B", analysis: "亚洲地形以高原和山地为主，平均海拔较高，中部是青藏高原和帕米尔高原，平原多分布在大陆边缘。", mastered: false, collected: false },
  { id: "geo-7b-xj-002", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "注入北冰洋的亚洲河流是（　　）", options: ["A. 长江", "B. 恒河", "C. 鄂毕河", "D. 湄公河"], answer: "C", analysis: "亚洲中部高四周低，河流呈放射状流向四周。鄂毕河注入北冰洋，长江注入太平洋，恒河注入印度洋，湄公河注入太平洋。", mastered: false, collected: false },
  { id: "geo-7b-xj-003", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "下列亚洲之最，正确的是（　　）", options: ["A. 世界最高峰—乞力马扎罗山", "B. 世界最大的半岛—阿拉伯半岛", "C. 世界最大的平原—东欧平原", "D. 世界最大的群岛—日本群岛"], answer: "B", analysis: "阿拉伯半岛是世界最大的半岛。世界最高峰是珠穆朗玛峰，世界最大的平原是亚马孙平原，世界最大的群岛是马来群岛。", mastered: false, collected: false },
  { id: "geo-7b-xj-004", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "日本工业主要分布在（　　）", options: ["A. 日本海沿岸", "B. 太平洋沿岸和濑户内海沿岸", "C. 北海道", "D. 九州岛南部"], answer: "B", analysis: "日本工业主要分布在太平洋沿岸和濑户内海沿岸，这里港口条件好，便于进口原料和出口产品，称为「太平洋沿岸工业带」。", mastered: false, collected: false },
  { id: "geo-7b-xj-005", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "日本的传统服装是（　　）", options: ["A. 旗袍", "B. 和服", "C. 纱丽", "D. 韩服"], answer: "B", analysis: "和服是日本的传统民族服装。旗袍是中国传统服装，纱丽是印度传统服装，韩服是韩国传统服装。", mastered: false, collected: false },
  { id: "geo-7b-xj-006", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "东南亚的气候类型主要是（　　）", options: ["A. 温带季风气候", "B. 热带雨林气候和热带季风气候", "C. 地中海气候", "D. 温带海洋性气候"], answer: "B", analysis: "东南亚以热带雨林气候和热带季风气候为主，全年高温，降水丰富，有利于水稻种植和热带经济作物生长。", mastered: false, collected: false },
  { id: "geo-7b-xj-007", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "湄公河在中国境内被称为（　　）", options: ["A. 怒江", "B. 澜沧江", "C. 金沙江", "D. 雅鲁藏布江"], answer: "B", analysis: "湄公河发源于中国青藏高原，在中国境内称为澜沧江，流经东南亚后称为湄公河，是亚洲重要的国际河流。", mastered: false, collected: false },
  { id: "geo-7b-xj-008", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "印度最大的城市是（　　）", options: ["A. 新德里", "B. 孟买", "C. 加尔各答", "D. 班加罗尔"], answer: "B", analysis: "孟买是印度最大的城市和港口，也是印度经济中心。新德里是首都，加尔各答是东部最大城市，班加罗尔是「印度硅谷」。", mastered: false, collected: false },
  { id: "geo-7b-xj-009", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "俄罗斯最重要的交通方式是（　　）", options: ["A. 公路", "B. 铁路", "C. 航空", "D. 海运"], answer: "B", analysis: "俄罗斯地域广大，铁路是最重要的运输方式，以莫斯科为中心呈放射状分布，西伯利亚大铁路横贯东西。", mastered: false, collected: false },
  { id: "geo-7b-xj-010", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "中东地区的居民多信仰（　　）", options: ["A. 佛教", "B. 基督教", "C. 伊斯兰教", "D. 印度教"], answer: "C", analysis: "中东地区是伊斯兰教的发源地，居民大多信仰伊斯兰教，阿拉伯人是主要民族，因此中东又称阿拉伯世界。", mastered: false, collected: false },
  { id: "geo-7b-xj-011", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "欧洲西部的地形以什么为主（　　）", options: ["A. 高原", "B. 山地", "C. 平原", "D. 盆地"], answer: "C", analysis: "欧洲西部地形以平原为主，主要有西欧平原、波德平原等，平均海拔低，是世界上平均海拔最低的大洲。", mastered: false, collected: false },
  { id: "geo-7b-xj-012", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "非洲最高的山峰是（　　）", options: ["A. 珠穆朗玛峰", "B. 乞力马扎罗山", "C. 勃朗峰", "D. 阿空加瓜山"], answer: "B", analysis: "乞力马扎罗山位于坦桑尼亚境内，海拔5895米，是非洲最高峰，虽位于赤道附近，山顶却终年积雪。", mastered: false, collected: false },
  { id: "geo-7b-xj-013", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "澳大利亚的首都是（　　）", options: ["A. 悉尼", "B. 墨尔本", "C. 堪培拉", "D. 珀斯"], answer: "C", analysis: "堪培拉是澳大利亚首都，是政治中心。悉尼是最大城市和港口，墨尔本是第二大城市。", mastered: false, collected: false },
  { id: "geo-7b-xj-014", subject: "geography", grade: "七年级下册", version: "湘教版", type: "single", stem: "美国的首都是（　　）", options: ["A. 纽约", "B. 华盛顿", "C. 洛杉矶", "D. 芝加哥"], answer: "B", analysis: "华盛顿是美国首都，位于哥伦比亚特区。纽约是最大城市和港口，洛杉矶和芝加哥也是重要城市。", mastered: false, collected: false },
  { id: "geo-7b-xj-015", subject: "geography", grade: "七年级下册", version: "湘教版", type: "judge", stem: "巴西的官方语言是葡萄牙语。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "巴西曾经是葡萄牙殖民地，因此官方语言是葡萄牙语，这是拉丁美洲唯一以葡萄牙语为官方语言的国家。", mastered: false, collected: false },

  // ===== 地理 商务星球版 =====
  { id: "geo-7b-sw-001", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "亚洲季风气候显著的原因是（　　）", options: ["A. 地形复杂", "B. 海陆位置", "C. 纬度位置", "D. 洋流影响"], answer: "B", analysis: "亚洲地处世界最大大陆东部，面临世界最大大洋，海陆热力差异显著，形成了世界上最显著的季风气候。", mastered: false, collected: false },
  { id: "geo-7b-sw-002", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "亚洲河流流向的特点是（　　）", options: ["A. 自西向东", "B. 自东向西", "C. 呈放射状流向四周", "D. 自北向南"], answer: "C", analysis: "亚洲地势中部高四周低，河流呈放射状流向四周，分别注入北冰洋、太平洋和印度洋。", mastered: false, collected: false },
  { id: "geo-7b-sw-003", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "日本的国土组成是（　　）", options: ["A. 两大岛", "B. 三大岛", "C. 四大岛", "D. 五大岛"], answer: "C", analysis: "日本由北海道、本州、四国、九州四大岛及附近海域组成，其中本州岛是最大的岛屿。", mastered: false, collected: false },
  { id: "geo-7b-sw-004", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "日本的气候类型主要是（　　）", options: ["A. 温带大陆性气候", "B. 温带季风气候和亚热带季风气候", "C. 热带雨林气候", "D. 地中海气候"], answer: "B", analysis: "日本主要受温带季风气候和亚热带季风气候影响，由于是岛国，气候具有海洋性特征，降水较多。", mastered: false, collected: false },
  { id: "geo-7b-sw-005", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "东南亚最重要的经济作物是（　　）", options: ["A. 水稻", "B. 天然橡胶", "C. 棉花", "D. 大豆"], answer: "B", analysis: "东南亚是世界上天然橡胶、油棕、椰子等热带经济作物的最大产区，泰国是世界最大的天然橡胶出口国。", mastered: false, collected: false },
  { id: "geo-7b-sw-006", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "马六甲海峡沟通的两个大洋是（　　）", options: ["A. 太平洋和大西洋", "B. 太平洋和印度洋", "C. 印度洋和大西洋", "D. 北冰洋和太平洋"], answer: "B", analysis: "马六甲海峡位于马来半岛和苏门答腊岛之间，沟通太平洋和印度洋，是重要的海上通道，被称为「十字路口」的咽喉。", mastered: false, collected: false },
  { id: "geo-7b-sw-007", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "印度著名的软件产业城市是（　　）", options: ["A. 孟买", "B. 新德里", "C. 班加罗尔", "D. 加尔各答"], answer: "C", analysis: "班加罗尔是印度著名的软件产业中心，被称为「印度硅谷」，印度软件产业发达，是世界上重要的软件出口国。", mastered: false, collected: false },
  { id: "geo-7b-sw-008", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "俄罗斯的气候特点是（　　）", options: ["A. 全年高温", "B. 冬季长而寒冷，夏季短而温暖", "C. 四季如春", "D. 全年干燥"], answer: "B", analysis: "俄罗斯以温带大陆性气候为主，冬季漫长而寒冷，夏季短促而温暖，气温年较差大，降水较少。", mastered: false, collected: false },
  { id: "geo-7b-sw-009", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "中东石油主要分布在（　　）", options: ["A. 红海沿岸", "B. 波斯湾及其沿岸地区", "C. 地中海沿岸", "D. 阿拉伯海沿岸"], answer: "B", analysis: "中东石油主要分布在波斯湾及其沿岸地区，沙特阿拉伯、伊朗、伊拉克、科威特是主要产油国。", mastered: false, collected: false },
  { id: "geo-7b-sw-010", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "欧洲西部旅游业发达，下列景点属于法国的是（　　）", options: ["A. 埃菲尔铁塔", "B. 大本钟", "C. 比萨斜塔", "D. 风车"], answer: "A", analysis: "埃菲尔铁塔位于法国巴黎。大本钟在英国伦敦，比萨斜塔在意大利，风车是荷兰的标志。", mastered: false, collected: false },
  { id: "geo-7b-sw-011", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "撒哈拉以南非洲的经济特点是（　　）", options: ["A. 工业发达", "B. 以初级产品为主", "C. 高科技产业为主", "D. 服务业为主"], answer: "B", analysis: "撒哈拉以南非洲经济相对落后，以出口初级产品为主，如农产品、矿产等，工业基础薄弱，经济发展缓慢。", mastered: false, collected: false },
  { id: "geo-7b-sw-012", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "澳大利亚经济的支柱产业是（　　）", options: ["A. 农业", "B. 畜牧业", "C. 服务业", "D. 采矿业"], answer: "C", analysis: "20世纪70年代以来，澳大利亚服务业发展迅速，已成为国民经济支柱产业。农牧业和采矿业也是重要产业。", mastered: false, collected: false },
  { id: "geo-7b-sw-013", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "美国农业带中，位于五大湖附近的是（　　）", options: ["A. 棉花带", "B. 玉米带", "C. 乳畜带", "D. 小麦区"], answer: "C", analysis: "乳畜带位于美国东北部和五大湖附近，这里城市密集，人口众多，对乳肉产品需求量大，适合发展乳畜业。", mastered: false, collected: false },
  { id: "geo-7b-sw-014", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "single", stem: "巴西最显著的人口特征是（　　）", options: ["A. 人口稀少", "B. 白种人占多数", "C. 种族复杂，混血种人多", "D. 黄种人为主"], answer: "C", analysis: "巴西人口种族复杂，白种人占一半多，混血种人约占40%，还有黑种人、黄种人等，形成独特的巴西文化。", mastered: false, collected: false },
  { id: "geo-7b-sw-015", subject: "geography", grade: "七年级下册", version: "商务星球版", type: "judge", stem: "欧洲西部是世界上发达国家最为集中的地区。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "欧洲西部是世界上发达国家最为集中的地区，多数国家属于发达国家，经济发达，生活水平高。", mastered: false, collected: false },

  // ===== 地理 中图版 =====
  { id: "geo-7b-zt-001", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "亚洲与欧洲的分界线不包括（　　）", options: ["A. 乌拉尔山", "B. 乌拉尔河", "C. 苏伊士运河", "D. 大高加索山"], answer: "C", analysis: "亚欧分界线是乌拉尔山、乌拉尔河、大高加索山、土耳其海峡等。苏伊士运河是亚非分界线。", mastered: false, collected: false },
  { id: "geo-7b-zt-002", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "亚洲面积最大的气候类型是（　　）", options: ["A. 热带季风气候", "B. 温带季风气候", "C. 温带大陆性气候", "D. 寒带气候"], answer: "C", analysis: "温带大陆性气候在亚洲分布面积最大，主要分布在亚洲内陆地区，由于远离海洋，气候干燥，降水少。", mastered: false, collected: false },
  { id: "geo-7b-zt-003", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "日本富士山是（　　）", options: ["A. 死火山", "B. 活火山", "C. 休眠火山", "D. 不是火山"], answer: "B", analysis: "富士山是日本最高峰，海拔3776米，是一座活火山，最近一次喷发在1707年，是日本的象征。", mastered: false, collected: false },
  { id: "geo-7b-zt-004", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "日本经济发展的有利条件是（　　）", options: ["A. 资源丰富", "B. 劳动力充足", "C. 海岸线曲折多港湾", "D. 国内市场广阔"], answer: "C", analysis: "日本海岸线曲折，多优良港湾，有利于进口原料、出口产品，这是日本发展经济的有利条件。但资源贫乏、国内市场狭小。", mastered: false, collected: false },
  { id: "geo-7b-zt-005", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "东南亚华人和华侨最多的国家是（　　）", options: ["A. 泰国", "B. 马来西亚", "C. 印度尼西亚", "D. 新加坡"], answer: "C", analysis: "东南亚是世界上华人和华侨分布最集中的地区，印度尼西亚华人和华侨数量最多。新加坡华人比例最高。", mastered: false, collected: false },
  { id: "geo-7b-zt-006", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "印度主要的粮食作物是（　　）", options: ["A. 小麦和玉米", "B. 水稻和小麦", "C. 高粱和玉米", "D. 水稻和棉花"], answer: "B", analysis: "印度主要粮食作物是水稻和小麦，水稻主要分布在降水丰富的东北部，小麦主要分布在降水较少的西北部。", mastered: false, collected: false },
  { id: "geo-7b-zt-007", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "俄罗斯的首都是（　　）", options: ["A. 圣彼得堡", "B. 莫斯科", "C. 海参崴", "D. 新西伯利亚"], answer: "B", analysis: "莫斯科是俄罗斯首都，全国最大城市和政治、经济、文化、交通中心。圣彼得堡是第二大城市和港口。", mastered: false, collected: false },
  { id: "geo-7b-zt-008", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "中东地区的地形以什么为主（　　）", options: ["A. 平原", "B. 高原", "C. 山地", "D. 盆地"], answer: "B", analysis: "中东地区地形以高原为主，平原面积狭小，主要有阿拉伯高原、伊朗高原等，尼罗河谷地和两河流域是重要平原。", mastered: false, collected: false },
  { id: "geo-7b-zt-009", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "欧洲西部海岸线特点是（　　）", options: ["A. 平直", "B. 曲折", "C. 短小", "D. 简单"], answer: "B", analysis: "欧洲西部海岸线十分曲折，多半岛、岛屿、海湾和内海，有利于航海业和对外贸易的发展。", mastered: false, collected: false },
  { id: "geo-7b-zt-010", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "非洲最大的海湾是（　　）", options: ["A. 几内亚湾", "B. 亚丁湾", "C. 红海", "D. 地中海"], answer: "A", analysis: "几内亚湾是非洲最大的海湾，位于非洲西部赤道附近，沿岸有尼日利亚、加蓬等国家。", mastered: false, collected: false },
  { id: "geo-7b-zt-011", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "澳大利亚的气候分布特点是（　　）", options: ["A. 东岸多西岸少", "B. 呈半环状分布", "C. 南北对称", "D. 东高西低"], answer: "B", analysis: "澳大利亚气候呈半环状分布，从北、东、南三面沿海向内陆，由热带雨林气候逐渐过渡到热带草原气候和热带沙漠气候。", mastered: false, collected: false },
  { id: "geo-7b-zt-012", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "美国的国旗上有多少条条纹（　　）", options: ["A. 10条", "B. 13条", "C. 50条", "D. 7条"], answer: "B", analysis: "美国国旗有13条红白相间的条纹，代表最初独立的13个殖民地；50颗白星代表现在的50个州。", mastered: false, collected: false },
  { id: "geo-7b-zt-013", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "巴西的首都是（　　）", options: ["A. 里约热内卢", "B. 圣保罗", "C. 巴西利亚", "D. 萨尔瓦多"], answer: "C", analysis: "巴西首都原为里约热内卢，1960年迁至巴西利亚，位于内陆高原上，是政治中心。圣保罗是最大城市。", mastered: false, collected: false },
  { id: "geo-7b-zt-014", subject: "geography", grade: "七年级下册", version: "中图版", type: "single", stem: "极地地区中，跨经度最广的大洲是（　　）", options: ["A. 亚洲", "B. 非洲", "C. 北美洲", "D. 南极洲"], answer: "D", analysis: "南极洲位于南极圈内，跨所有经度，是世界上跨经度最广的大洲，也是海拔最高的大洲。", mastered: false, collected: false },
  { id: "geo-7b-zt-015", subject: "geography", grade: "七年级下册", version: "中图版", type: "judge", stem: "北极地区比南极地区更冷。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "南极地区比北极地区更冷，因为南极是陆地，海拔高，冰雪覆盖，反射率高；北极是海洋，比热容大，温度相对较高。", mastered: false, collected: false },

  // ===== 地理 粤人版 =====
  { id: "geo-7b-yr-001", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "亚洲众多河流中，注入太平洋的是（　　）", options: ["A. 印度河", "B. 幼发拉底河", "C. 长江", "D. 勒拿河"], answer: "C", analysis: "长江注入太平洋。印度河注入印度洋，幼发拉底河注入波斯湾，勒拿河注入北冰洋。", mastered: false, collected: false },
  { id: "geo-7b-yr-002", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "亚洲地形对河流的影响是（　　）", options: ["A. 河流短小", "B. 河流呈放射状流向四周", "C. 河流都流入海洋", "D. 河流都向东流"], answer: "B", analysis: "亚洲地势中部高四周低，导致河流呈放射状流向四周海洋，这种地势也使得亚洲水能资源丰富。", mastered: false, collected: false },
  { id: "geo-7b-yr-003", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "日本被称为「火山地震国」的原因是（　　）", options: ["A. 位于板块内部", "B. 位于环太平洋火山地震带", "C. 地形平坦", "D. 气候温暖"], answer: "B", analysis: "日本位于亚欧板块和太平洋板块交界处，属于环太平洋火山地震带，地壳运动活跃，多火山地震。", mastered: false, collected: false },
  { id: "geo-7b-yr-004", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "日本文化特点是（　　）", options: ["A. 单一文化", "B. 东西方文化兼容", "C. 只有西方文化", "D. 只有东方文化"], answer: "B", analysis: "日本文化具有东西方兼容的特点，既保留传统文化如茶道、和服，又吸收西方现代文化，形成独特文化。", mastered: false, collected: false },
  { id: "geo-7b-yr-005", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "东南亚重要的稻米出口国是（　　）", options: ["A. 缅甸、泰国、越南", "B. 马来西亚、新加坡", "C. 印度尼西亚、菲律宾", "D. 老挝、柬埔寨"], answer: "A", analysis: "缅甸、泰国、越南是世界重要的稻米出口国，东南亚气候高温多雨，适合水稻生长，是传统稻米产区。", mastered: false, collected: false },
  { id: "geo-7b-yr-006", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "中南半岛上人口和城市主要分布在（　　）", options: ["A. 山区", "B. 高原", "C. 河流沿岸和河口三角洲", "D. 沙漠"], answer: "C", analysis: "中南半岛人口和城市主要分布在河流沿岸和河口三角洲，这里地形平坦、土壤肥沃、水源充足、交通便利。", mastered: false, collected: false },
  { id: "geo-7b-yr-007", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "印度服务外包产业的特点是（　　）", options: ["A. 以制造业为主", "B. 以软件产业为主", "C. 以农业为主", "D. 以采矿业为主"], answer: "B", analysis: "印度服务外包产业以软件产业为主，被称为「世界办公室」，承接全球软件外包业务，班加罗尔是中心。", mastered: false, collected: false },
  { id: "geo-7b-yr-008", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "俄罗斯最长的河流是（　　）", options: ["A. 伏尔加河", "B. 鄂毕河", "C. 叶尼塞河", "D. 勒拿河"], answer: "A", analysis: "伏尔加河是俄罗斯最长的河流，全长3690千米，是欧洲最长河流，被俄罗斯人称为「母亲河」，注入里海。", mastered: false, collected: false },
  { id: "geo-7b-yr-009", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "中东地区地形主要是（　　）", options: ["A. 平原", "B. 高原", "C. 盆地", "D. 丘陵"], answer: "B", analysis: "中东地区地形以高原为主，主要有阿拉伯高原、安纳托利亚高原、伊朗高原等，平原面积小。", mastered: false, collected: false },
  { id: "geo-7b-yr-010", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "欧洲西部畜牧业发达的自然原因是（　　）", options: ["A. 地形平坦", "B. 气候温和湿润", "C. 河流众多", "D. 土壤肥沃"], answer: "B", analysis: "欧洲西部以温带海洋性气候为主，全年温和湿润，适合多汁牧草生长，这是畜牧业发达的主要原因。", mastered: false, collected: false },
  { id: "geo-7b-yr-011", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "撒哈拉以南非洲最典型的地形是（　　）", options: ["A. 平原", "B. 盆地", "C. 高原", "D. 山地"], answer: "C", analysis: "撒哈拉以南非洲地形以高原为主，被称为「高原大陆」，主要有东非高原、南非高原、埃塞俄比亚高原等。", mastered: false, collected: false },
  { id: "geo-7b-yr-012", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "澳大利亚特有的植物是（　　）", options: ["A. 仙人掌", "B. 桉树", "C. 椰树", "D. 橡胶树"], answer: "B", analysis: "澳大利亚有特有植物桉树，是考拉的主要食物。澳大利亚长期孤立，生物进化独特，有许多特有动植物。", mastered: false, collected: false },
  { id: "geo-7b-yr-013", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "美国地形分布的特点是（　　）", options: ["A. 东高西低", "B. 西高东低", "C. 南高北低", "D. 南北高，中间低"], answer: "D", analysis: "美国地形分为三大区：西部是高山（落基山脉），东部是低矮山地（阿巴拉契亚山脉），中部是广阔平原，南北高，中间低。", mastered: false, collected: false },
  { id: "geo-7b-yr-014", subject: "geography", grade: "七年级下册", version: "粤人版", type: "single", stem: "巴西最大的城市是（　　）", options: ["A. 巴西利亚", "B. 里约热内卢", "C. 圣保罗", "D. 萨尔瓦多"], answer: "C", analysis: "圣保罗是巴西最大城市和工业中心，位于东南沿海。里约热内卢是第二大城市和重要港口。", mastered: false, collected: false },
  { id: "geo-7b-yr-015", subject: "geography", grade: "七年级下册", version: "粤人版", type: "judge", stem: "南极地区是地球上最冷的地方。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "南极地区是地球上最冷的地方，极端最低气温可达-89.2℃，比北极地区更冷，被称为「冰雪高原」。", mastered: false, collected: false },

  // ===== 地理 晋教版 =====
  { id: "geo-7b-jj-001", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "世界上跨纬度最广的大洲是（　　）", options: ["A. 亚洲", "B. 非洲", "C. 北美洲", "D. 南美洲"], answer: "A", analysis: "亚洲是跨纬度最广的大洲，从北纬81°到南纬11°，跨寒、温、热三带，气候类型复杂多样。", mastered: false, collected: false },
  { id: "geo-7b-jj-002", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "亚洲东部岛屿分布特点是（　　）", options: ["A. 呈弧形分布", "B. 呈直线分布", "C. 呈圆形分布", "D. 无规律"], answer: "A", analysis: "亚洲东部岛屿呈弧形分布，称为岛弧，如千岛群岛、日本群岛、琉球群岛、菲律宾群岛等，是板块碰撞的结果。", mastered: false, collected: false },
  { id: "geo-7b-jj-003", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "日本最大的平原是（　　）", options: ["A. 关东平原", "B. 大阪平原", "C. 浓尾平原", "D. 石狩平原"], answer: "A", analysis: "关东平原是日本最大的平原，位于本州岛东南部，东京都位于此，是日本政治、经济、文化中心。", mastered: false, collected: false },
  { id: "geo-7b-jj-004", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "日本最大的岛屿是（　　）", options: ["A. 北海道", "B. 本州", "C. 四国", "D. 九州"], answer: "B", analysis: "本州岛是日本最大的岛屿，也是政治、经济、文化中心，东京、大阪、名古屋等大城市都位于本州岛。", mastered: false, collected: false },
  { id: "geo-7b-jj-005", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "东南亚的地形特点是（　　）", options: ["A. 北高南低", "B. 中山河相间，南群岛分布", "C. 东高西低", "D. 地势平坦"], answer: "B", analysis: "东南亚地形特点是北部中南半岛山河相间、纵列分布，南部马来群岛岛屿众多，地形崎岖。", mastered: false, collected: false },
  { id: "geo-7b-jj-006", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "印度河主要流经的国家是（　　）", options: ["A. 印度", "B. 巴基斯坦", "C. 孟加拉国", "D. 尼泊尔"], answer: "B", analysis: "印度河主要流经巴基斯坦，是巴基斯坦重要的灌溉水源，注入阿拉伯海。印度河虽然名为「印度」，但主要在巴基斯坦境内。", mastered: false, collected: false },
  { id: "geo-7b-jj-007", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "俄罗斯乌拉尔山以西的部分属于（　　）", options: ["A. 亚洲", "B. 欧洲", "C. 非洲", "D. 美洲"], answer: "B", analysis: "乌拉尔山是亚欧分界线，以西是东欧平原，属于欧洲；以东是西西伯利亚平原，属于亚洲。俄罗斯地跨亚欧两洲。", mastered: false, collected: false },
  { id: "geo-7b-jj-008", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "苏伊士运河沟通的两个海域是（　　）", options: ["A. 地中海和红海", "B. 黑海和地中海", "C. 红海和阿拉伯海", "D. 地中海和大西洋"], answer: "A", analysis: "苏伊士运河沟通地中海和红海，连接大西洋和印度洋，是重要的国际航运通道，大大缩短了东西方航程。", mastered: false, collected: false },
  { id: "geo-7b-jj-009", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "欧洲西部的居民主要为（　　）", options: ["A. 黄种人", "B. 白种人", "C. 黑种人", "D. 混血种人"], answer: "B", analysis: "欧洲西部居民主要为白种人，人口密度较大，是世界上人口稠密的地区之一，城市化水平高。", mastered: false, collected: false },
  { id: "geo-7b-jj-010", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "非洲最大的岛屿是（　　）", options: ["A. 苏门答腊岛", "B. 马达加斯加岛", "C. 斯里兰卡岛", "D. 新几内亚岛"], answer: "B", analysis: "马达加斯加岛是非洲最大的岛屿，位于非洲东南部，属于马达加斯加国，生物种类独特。", mastered: false, collected: false },
  { id: "geo-7b-jj-011", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "澳大利亚位于哪个半球（　　）", options: ["A. 北半球", "B. 南半球", "C. 西半球", "D. 北西半球"], answer: "B", analysis: "澳大利亚位于南半球，季节与北半球相反，1月是夏季，7月是冬季。澳大利亚是世界上唯一独占一块大陆的国家。", mastered: false, collected: false },
  { id: "geo-7b-jj-012", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "美国人口最多的城市是（　　）", options: ["A. 华盛顿", "B. 纽约", "C. 洛杉矶", "D. 芝加哥"], answer: "B", analysis: "纽约是美国人口最多的城市，也是最大港口和金融中心。华盛顿是首都，洛杉矶是第二大城市。", mastered: false, collected: false },
  { id: "geo-7b-jj-013", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "巴西最大的平原是（　　）", options: ["A. 亚马孙平原", "B. 拉普拉塔平原", "C. 巴西高原", "D. 圭亚那高原"], answer: "A", analysis: "亚马孙平原是巴西最大的平原，也是世界最大的平原，由亚马孙河冲积而成，分布着世界最大的热带雨林。", mastered: false, collected: false },
  { id: "geo-7b-jj-014", subject: "geography", grade: "七年级下册", version: "晋教版", type: "single", stem: "南极洲特有的动物是（　　）", options: ["A. 北极熊", "B. 企鹅", "C. 海豹", "D. 鲸鱼"], answer: "B", analysis: "企鹅是南极洲特有的动物，能在严寒中生存。北极熊是北极地区特有动物，海豹和鲸鱼在两极都有分布。", mastered: false, collected: false },
  { id: "geo-7b-jj-015", subject: "geography", grade: "七年级下册", version: "晋教版", type: "judge", stem: "亚马孙河是世界上流量最大的河流。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "亚马孙河是世界上流量最大、流域面积最广的河流，流量约占世界河流总流量的20%，发源于安第斯山脉，注入大西洋。", mastered: false, collected: false },

  // ===== 地理 中图版（北京）=====
  { id: "geo-7b-ztbj-001", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "亚洲东西距离长的意义是（　　）", options: ["A. 气候单一", "B. 时间差异大", "C. 地形平坦", "D. 河流短小"], answer: "B", analysis: "亚洲东西距离长，跨经度广，导致东西部时间差异大，东部沿海和西部内陆存在明显的时间差。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-002", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "青藏高原被称为「世界屋脊」的原因是（　　）", options: ["A. 海拔最高", "B. 面积最大", "C. 人口最多", "D. 资源最丰富"], answer: "A", analysis: "青藏高原平均海拔4000米以上，是世界上海拔最高的高原，被称为「世界屋脊」，位于亚洲中部。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-003", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "日本地震频发的原因是（　　）", options: ["A. 位于板块内部", "B. 位于板块交界处", "C. 地形平坦", "D. 气候寒冷"], answer: "B", analysis: "日本位于亚欧板块和太平洋板块交界处，地壳运动活跃，多火山地震。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-004", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "东南亚位于「十字路口」的位置，主要指（　　）", options: ["A. 亚洲和非洲之间", "B. 亚洲和大洋洲、太平洋和印度洋之间", "C. 欧洲和亚洲之间", "D. 北美洲和南美洲之间"], answer: "B", analysis: "东南亚位于亚洲与大洋洲、太平洋与印度洋之间的「十字路口」，马六甲海峡是重要海上通道。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-005", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "恒河注入（　　）", options: ["A. 阿拉伯海", "B. 孟加拉湾", "C. 印度洋", "D. 太平洋"], answer: "B", analysis: "恒河是印度重要河流，发源于喜马拉雅山南麓，流经印度北部和孟加拉国，注入孟加拉湾。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-006", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "俄罗斯森林资源主要分布在（　　）", options: ["A. 东欧平原", "B. 西西伯利亚平原", "C. 中西伯利亚高原", "D. 整个西伯利亚地区"], answer: "D", analysis: "俄罗斯森林资源丰富，主要分布在西伯利亚地区，是世界上森林面积最大的国家，以亚寒带针叶林为主。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-007", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "中东地区气候特点是（　　）", options: ["A. 湿润多雨", "B. 终年炎热干燥", "C. 四季分明", "D. 全年寒冷"], answer: "B", analysis: "中东地区主要为热带沙漠气候，终年炎热干燥，降水稀少，这是水资源匮乏的主要原因。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-008", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "欧洲西部的内力作用形成的地形是（　　）", options: ["A. 平原", "B. 山地", "C. 海岸线曲折", "D. 冰川地形"], answer: "C", analysis: "欧洲西部海岸线曲折，多半岛、岛屿、海湾和内海，这是地壳运动等内力作用形成的。冰川作用形成峡湾。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-009", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "东非大裂谷形成的原因是（　　）", options: ["A. 流水侵蚀", "B. 板块张裂", "C. 火山喷发", "D. 冰川作用"], answer: "B", analysis: "东非大裂谷是板块张裂运动形成的，地壳断裂下陷，形成世界陆地上最长的裂谷带，被称为「地球的伤疤」。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-010", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "澳大利亚被称为「骑在羊背上的国家」的原因是（　　）", options: ["A. 羊的数量多", "B. 畜牧业发达", "C. 羊毛产量出口量世界第一", "D. 羊肉出口最多"], answer: "C", analysis: "澳大利亚羊毛产量和出口量都居世界第一，因此被称为「骑在羊背上的国家」。畜牧业是重要产业。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-011", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "美国的高新技术产业基地是（　　）", options: ["A. 纽约", "B. 华盛顿", "C. 硅谷", "D. 底特律"], answer: "C", analysis: "硅谷位于美国旧金山附近，是美国最大的高新技术产业基地，以电子工业为主，聚集了大量高科技公司。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-012", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "巴西热带雨林的环境效益是（　　）", options: ["A. 提供木材", "B. 调节气候", "C. 提供耕地", "D. 提供药材"], answer: "B", analysis: "巴西热带雨林通过光合作用吸收二氧化碳、释放氧气，调节全球气候，被称为「地球之肺」，具有巨大的环境效益。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-013", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "南极地区的代表动物是（　　）", options: ["A. 北极熊", "B. 企鹅", "C. 骆驼", "D. 袋鼠"], answer: "B", analysis: "企鹅是南极地区的代表动物，能在严寒环境中生存。北极熊是北极地区代表动物。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-014", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "single", stem: "下列关于两极地区的叙述，正确的是（　　）", options: ["A. 都有定居人口", "B. 南极地区是陆地，北极地区是海洋", "C. 北极地区比南极地区冷", "D. 都没有动物"], answer: "B", analysis: "南极地区是南极大陆，是陆地；北极地区是北冰洋，是海洋。南极比北极更冷，北极有定居人口，两极都有动物。", mastered: false, collected: false },
  { id: "geo-7b-ztbj-015", subject: "geography", grade: "七年级下册", version: "中图版（北京）", type: "judge", stem: "撒哈拉以南非洲被称为「黑非洲」。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "撒哈拉以南非洲是黑种人的故乡，黑种人占绝大多数，因此被称为「黑非洲」。", mastered: false, collected: false },

  // ===== 地理 仁爱科普版 =====
  { id: "geo-7b-ra-001", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "亚洲地形对气候的影响是（　　）", options: ["A. 使气候单一", "B. 使气候复杂多样", "C. 使气候寒冷", "D. 使气候炎热"], answer: "B", analysis: "亚洲地形复杂，高原山地多，导致气候复杂多样，同一纬度不同海拔地区气候差异很大。", mastered: false, collected: false },
  { id: "geo-7b-ra-002", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "日本工业集中分布在太平洋沿岸的原因是（　　）", options: ["A. 资源丰富", "B. 港口条件好", "C. 气候适宜", "D. 人口稀少"], answer: "B", analysis: "日本工业集中在太平洋沿岸和濑户内海沿岸，主要原因是这里港口条件优良，便于进口原料、燃料，出口工业产品。", mastered: false, collected: false },
  { id: "geo-7b-ra-003", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "东南亚成为世界热带经济作物产区的主要原因是（　　）", options: ["A. 土壤肥沃", "B. 气候湿热", "C. 劳动力丰富", "D. 技术先进"], answer: "B", analysis: "东南亚以热带雨林气候和热带季风气候为主，全年高温多雨，湿热的气候适合天然橡胶、油棕、椰子等热带经济作物生长。", mastered: false, collected: false },
  { id: "geo-7b-ra-004", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "印度主要的地形区是（　　）", options: ["A. 平原", "B. 高原", "C. 山地", "D. 盆地"], answer: "B", analysis: "印度地形分为三部分：北部是喜马拉雅山地，中部是恒河平原，南部是德干高原，德干高原是印度主要的地形区。", mastered: false, collected: false },
  { id: "geo-7b-ra-005", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "俄罗斯自然资源的特点是（　　）", options: ["A. 种类少", "B. 储量小", "C. 种类多，储量大，自给自足", "D. 依赖进口"], answer: "C", analysis: "俄罗斯自然资源种类多、储量大，能够自给自足，是世界重要的资源出口国，石油、天然气、煤炭等储量丰富。", mastered: false, collected: false },
  { id: "geo-7b-ra-006", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "中东地区成为热点地区的主要原因是（　　）", options: ["A. 气候炎热", "B. 文化差异", "C. 丰富的石油资源", "D. 地形崎岖"], answer: "C", analysis: "中东地区石油资源丰富，是大国争夺的焦点，加上民族、宗教矛盾和水资源的争夺，使其长期成为世界热点地区。", mastered: false, collected: false },
  { id: "geo-7b-ra-007", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "欧洲西部乳畜业发达的有利条件是（　　）", options: ["A. 气候寒冷", "B. 城市密集，市场广阔", "C. 地形崎岖", "D. 人口稀少"], answer: "B", analysis: "欧洲西部城市密集，人口众多，对乳畜产品需求量大，市场广阔，加上气候适合多汁牧草生长，乳畜业发达。", mastered: false, collected: false },
  { id: "geo-7b-ra-008", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "非洲人口自然增长率的特点是（　　）", options: ["A. 增长缓慢", "B. 增长最快", "C. 负增长", "D. 不变"], answer: "B", analysis: "非洲是世界上人口自然增长率最高的大洲，人口增长过快给粮食、环境、就业等带来巨大压力。", mastered: false, collected: false },
  { id: "geo-7b-ra-009", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "澳大利亚铁矿资源主要分布在（　　）", options: ["A. 东部", "B. 西部", "C. 南部", "D. 北部"], answer: "B", analysis: "澳大利亚铁矿资源主要分布在西部地区，铁矿石储量大、品位高，便于开采和出口，是重要的铁矿出口国。", mastered: false, collected: false },
  { id: "geo-7b-ra-010", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "美国五大湖地区的工业类型是（　　）", options: ["A. 高新技术产业", "B. 传统工业", "C. 轻工业", "D. 电子工业"], answer: "B", analysis: "美国五大湖地区是传统工业区，利用附近丰富的煤炭、铁矿资源和便利的水运，发展了钢铁、汽车等传统工业。", mastered: false, collected: false },
  { id: "geo-7b-ra-011", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "巴西主要的热带经济作物是（　　）", options: ["A. 咖啡、甘蔗、柑橘", "B. 茶叶、棉花", "C. 橡胶、椰子", "D. 大豆、花生"], answer: "A", analysis: "巴西咖啡、甘蔗、柑橘产量居世界第一，是重要的热带经济作物生产国和出口国。", mastered: false, collected: false },
  { id: "geo-7b-ra-012", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "极地地区的环境保护措施是（　　）", options: ["A. 大力开发资源", "B. 建立定居点", "C. 签订条约，和平利用", "D. 进行核试验"], answer: "C", analysis: "为了保护极地环境，国际社会签订了《南极条约》等，规定极地地区只用于和平目的，禁止军事活动和资源开发。", mastered: false, collected: false },
  { id: "geo-7b-ra-013", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "下列关于亚洲人口的叙述，正确的是（　　）", options: ["A. 人口稀少", "B. 人口最多", "C. 增长最慢", "D. 负增长"], answer: "B", analysis: "亚洲是世界上人口最多的大洲，人口约40多亿，占世界总人口的一半以上，东亚、东南亚、南亚是人口稠密区。", mastered: false, collected: false },
  { id: "geo-7b-ra-014", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "single", stem: "俄罗斯亚洲部分与欧洲部分相比（　　）", options: ["A. 亚洲部分人口多", "B. 欧洲部分人口多", "C. 两部分相等", "D. 亚洲部分经济发达"], answer: "B", analysis: "俄罗斯欧洲部分人口和城市密集，经济发达，是政治、经济、文化中心。亚洲部分虽然面积广大，但人口稀少，经济相对落后。", mastered: false, collected: false },
  { id: "geo-7b-ra-015", subject: "geography", grade: "七年级下册", version: "仁爱科普版", type: "judge", stem: "巴西的城市和人口主要分布在东南部沿海。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "巴西城市和人口主要分布在东南部沿海地区，这里气候适宜，交通便利，经济发达，圣保罗、里约热内卢等大城市都在这里。", mastered: false, collected: false },

  // ===== 地理 鲁教版（五四学制）=====
  { id: "geo-7b-lj-001", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "世界上跨东西距离最长的大洲是（　　）", options: ["A. 亚洲", "B. 非洲", "C. 北美洲", "D. 南美洲"], answer: "A", analysis: "亚洲是世界上跨东西距离最长的大洲，东西距离约8000多千米，跨经度约164°，时间差异很大。", mastered: false, collected: false },
  { id: "geo-7b-lj-002", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "亚洲气候复杂多样表现在（　　）", options: ["A. 只有热带气候", "B. 只有温带气候", "C. 跨寒温热三带，气候类型齐全", "D. 只有干旱气候"], answer: "C", analysis: "亚洲跨寒带、温带、热带三带，加上地形复杂，导致气候类型复杂多样，世界主要的气候类型在亚洲都有分布。", mastered: false, collected: false },
  { id: "geo-7b-lj-003", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "日本传统民居多采用木质结构的原因是（　　）", options: ["A. 木材便宜", "B. 多地震，木质结构抗震", "C. 木材丰富", "D. 木质美观"], answer: "B", analysis: "日本多地震，传统民居多采用木质结构，因为木质结构轻便、有弹性，抗震性能好，能减少地震造成的伤害。", mastered: false, collected: false },
  { id: "geo-7b-lj-004", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "东南亚的粮食作物以水稻为主的原因是（　　）", options: ["A. 土壤肥沃", "B. 气候高温多雨，适合水稻生长", "C. 劳动力少", "D. 市场需求小"], answer: "B", analysis: "东南亚以热带雨林气候和热带季风气候为主，全年高温多雨，水热条件好，适合水稻生长，水稻是主要粮食作物。", mastered: false, collected: false },
  { id: "geo-7b-lj-005", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "印度旱涝灾害频繁的原因是（　　）", options: ["A. 地形影响", "B. 季风不稳定", "C. 植被破坏", "D. 河流污染"], answer: "B", analysis: "印度以热带季风气候为主，西南季风强弱不稳定，来得早或退得晚易造成洪涝，来得晚或退得早易造成旱灾。", mastered: false, collected: false },
  { id: "geo-7b-lj-006", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "俄罗斯重工业发达的原因是（　　）", options: ["A. 资源丰富", "B. 技术先进", "C. 交通便利", "D. 市场广阔"], answer: "A", analysis: "俄罗斯矿产资源丰富，石油、天然气、煤、铁等储量大，为重工业发展提供了充足原料，重工业发达。", mastered: false, collected: false },
  { id: "geo-7b-lj-007", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "中东的石油主要运往（　　）", options: ["A. 亚洲", "B. 非洲", "C. 美国、日本、西欧", "D. 南美洲"], answer: "C", analysis: "中东石油主要输往美国、日本和西欧等发达国家，这些国家石油消费量大，但石油资源少，对中东石油依赖性强。", mastered: false, collected: false },
  { id: "geo-7b-lj-008", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "欧洲西部的工业特点是（　　）", options: ["A. 以重工业为主", "B. 以制造业为主", "C. 以采矿业为主", "D. 以农业为主"], answer: "B", analysis: "欧洲西部工业以制造业为主，进口原料、燃料，加工成工业品出口，制造业产值比重高，是世界工业发达地区。", mastered: false, collected: false },
  { id: "geo-7b-lj-009", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "撒哈拉以南非洲面临的主要问题是（　　）", options: ["A. 人口、粮食、环境问题", "B. 战争频繁", "C. 资源枯竭", "D. 气候寒冷"], answer: "A", analysis: "撒哈拉以南非洲由于人口增长过快，粮食短缺，过度开垦放牧导致环境恶化，形成人口、粮食、环境三大问题。", mastered: false, collected: false },
  { id: "geo-7b-lj-010", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "澳大利亚被称为「坐在矿车上的国家」的原因是（　　）", options: ["A. 矿产资源丰富", "B. 矿产种类少", "C. 依赖进口矿产", "D. 没有矿产"], answer: "A", analysis: "澳大利亚矿产资源丰富，铁矿、煤矿等储量大、品位高，矿产品出口量大，被称为「坐在矿车上的国家」。", mastered: false, collected: false },
  { id: "geo-7b-lj-011", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "美国农业现代化的表现是（　　）", options: ["A. 机械化、专业化", "B. 手工劳动", "C. 小农经营", "D. 单一经营"], answer: "A", analysis: "美国农业实现了机械化和区域专业化，形成多个农业带，生产效率高，是世界最大的农产品出口国。", mastered: false, collected: false },
  { id: "geo-7b-lj-012", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "巴西工业分布的特点是（　　）", options: ["A. 分布在亚马孙平原", "B. 集中在东南部沿海", "C. 分布在北部", "D. 分布在西部"], answer: "B", analysis: "巴西工业主要集中在东南部沿海地区，这里交通便利，人口密集，经济发达，圣保罗、里约热内卢是重要工业中心。", mastered: false, collected: false },
  { id: "geo-7b-lj-013", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "下列关于南极地区的叙述，正确的是（　　）", options: ["A. 是大西洋", "B. 是太平洋", "C. 是陆地", "D. 是北冰洋"], answer: "C", analysis: "南极地区是南极大陆，是陆地，平均海拔高，覆盖着厚厚的冰雪。北极地区是北冰洋，是海洋。", mastered: false, collected: false },
  { id: "geo-7b-lj-014", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "single", stem: "保护地球环境的措施不包括（　　）", options: ["A. 减少污染", "B. 植树造林", "C. 节约资源", "D. 大量砍伐森林"], answer: "D", analysis: "保护地球环境应减少污染、植树造林、节约资源，而大量砍伐森林会破坏生态环境，加剧水土流失和气候变化。", mastered: false, collected: false },
  { id: "geo-7b-lj-015", subject: "geography", grade: "七年级下册", version: "鲁教版（五四学制）", type: "judge", stem: "日本是一个多火山地震的岛国。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "日本位于环太平洋火山地震带上，处于亚欧板块和太平洋板块交界处，地壳运动活跃，多火山地震，是典型的岛国。", mastered: false, collected: false },

  // ===== 道法 统编版 =====
  { id: "pol-7b-tb-001", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "青春的创造力表现在（　　）", options: ["A. 敢于打破常规", "B. 遵守一切规则", "C. 拒绝接受新事物", "D. 盲目追求新奇"], answer: "A", analysis: "青春的创造力表现在敢于打破常规、追求创新、勇于尝试等方面。但打破常规不是违反法律和道德，而是创造性思考。", mastered: false, collected: false },
  { id: "pol-7b-tb-002", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "「行己有耻」要求我们（　　）", options: ["A. 知廉耻，懂荣辱", "B. 追求虚荣", "C. 不顾道德", "D. 放纵自己"], answer: "A", analysis: "「行己有耻」要求我们知廉耻、懂荣辱，有所为有所不为，树立底线意识，触碰道德底线的事情不做，违反法律的事情坚决不做。", mastered: false, collected: false },
  { id: "pol-7b-tb-003", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "「止于至善」的境界要求我们（　　）", options: ["A. 满足现状", "B. 追求更高的道德境界", "C. 苛求完美", "D. 盲目攀比"], answer: "B", analysis: "「止于至善」要求我们追求更高的道德境界，从小事做起，积少成多，积善成德，见贤思齐，向榜样学习。", mastered: false, collected: false },
  { id: "pol-7b-tb-004", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "下列关于男女同学交往的观点，正确的是（　　）", options: ["A. 避免交往", "B. 言谈得当，互尊互让", "C. 过分亲密", "D. 自我封闭"], answer: "B", analysis: "男女同学交往应言谈得当、互尊互让、自尊自爱、把握分寸，既要大方交往，又要注意方式，促进共同进步。", mastered: false, collected: false },
  { id: "pol-7b-tb-005", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "「独立思考」表现为（　　）", options: ["A. 不接受他人意见", "B. 有主见，不人云亦云", "C. 固执己见", "D. 反抗一切"], answer: "B", analysis: "独立思考表现为有主见、不人云亦云，能理性思考问题，不盲目从众，但也不是固执己见，能合理接受他人合理意见。", mastered: false, collected: false },
  { id: "pol-7b-tb-006", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "「批判性思维」的特点是（　　）", options: ["A. 否定一切", "B. 敢于对不合理的事情说「不」", "C. 抱怨生活", "D. 反对权威"], answer: "B", analysis: "批判性思维表现为敢于对不合理的事情说「不」，敢于表达不同观点，敢于向不合理的事情挑战，但不是否定一切。", mastered: false, collected: false },
  { id: "pol-7b-tb-007", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "下列关于情绪的说法，正确的是（　　）", options: ["A. 情绪不可控", "B. 情绪是多样的", "C. 情绪都是负面的", "D. 情绪一成不变"], answer: "B", analysis: "情绪是多样的，包括喜、怒、哀、惧等基本情绪，情绪会随着情境和时间变化，情绪是可以调节和管理的。", mastered: false, collected: false },
  { id: "pol-7b-tb-008", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "调节情绪的方法不包括（　　）", options: ["A. 转移注意", "B. 合理宣泄", "C. 改变认知评价", "D. 压抑情绪"], answer: "D", analysis: "调节情绪的方法包括转移注意、合理宣泄、改变认知评价、放松训练等。压抑情绪不利于身心健康，不是正确的调节方法。", mastered: false, collected: false },
  { id: "pol-7b-tb-009", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "情感与情绪的关系是（　　）", options: ["A. 完全相同", "B. 情感是稳定的，情绪是暂时的", "C. 互不影响", "D. 情绪比情感重要"], answer: "B", analysis: "情绪是短暂的、不稳定的，情感是相对稳定的、持久的。情感伴随情绪反应逐渐积累，情绪变化影响情感。", mastered: false, collected: false },
  { id: "pol-7b-tb-010", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "集体荣誉感来源于（　　）", options: ["A. 个人成绩", "B. 集体共同奋斗", "C. 竞争对手", "D. 物质奖励"], answer: "B", analysis: "集体荣誉感来源于集体成员的共同奋斗和成就，当集体取得成绩时，每个成员都会感到自豪，这种荣誉感增强集体凝聚力。", mastered: false, collected: false },
  { id: "pol-7b-tb-011", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "个人与集体的关系是（　　）", options: ["A. 个人高于集体", "B. 集体高于个人", "C. 个人在集体中成长", "D. 互相对立"], answer: "C", analysis: "个人与集体相互依存，个人在集体中成长，集体因个人而精彩。我们要处理好个人与集体的关系，自觉维护集体利益。", mastered: false, collected: false },
  { id: "pol-7b-tb-012", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "下列行为中，遵守纪律的是（　　）", options: ["A. 上课说话", "B. 按时完成作业", "C. 迟到早退", "D. 随意旷课"], answer: "B", analysis: "按时完成作业是遵守纪律的表现。上课说话、迟到早退、随意旷课都违反了学校纪律，是不遵守纪律的行为。", mastered: false, collected: false },
  { id: "pol-7b-tb-013", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "未成年人保护法规定，对未成年人保护的基本原则是（　　）", options: ["A. 尊重未成年人的人格尊严", "B. 严厉惩罚", "C. 限制自由", "D. 取消权利"], answer: "A", analysis: "未成年人保护法规定，尊重未成年人的人格尊严是基本原则之一，还要遵循适应未成年人身心发展规律、教育与保护相结合等原则。", mastered: false, collected: false },
  { id: "pol-7b-tb-014", subject: "politics", grade: "七年级下册", version: "统编版", type: "single", stem: "下列行为中，属于不良行为的是（　　）", options: ["A. 遵守交通规则", "B. 沉迷网络", "C. 按时上学", "D. 帮助同学"], answer: "B", analysis: "沉迷网络属于不良行为，会影响身心健康和学习。遵守交通规则、按时上学、帮助同学都是良好行为。", mastered: false, collected: false },
  { id: "pol-7b-tb-015", subject: "politics", grade: "七年级下册", version: "统编版", type: "judge", stem: "法律通过规定权利和义务来规范人们的行为。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "法律通过规定权利和义务来规范人们的行为，规定人们应该做什么、不应该做什么，为人们的行为提供准则。", mastered: false, collected: false },

  // ===== 道法 统编版（2024）=====
  { id: "pol-7b-tb24-001", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "青春期的心理矛盾表现为（　　）", options: ["A. 心理平静", "B. 渴望独立与依赖的矛盾", "C. 完全成熟", "D. 没有变化"], answer: "B", analysis: "青春期心理矛盾主要表现为渴望独立与依赖的矛盾、心理闭锁与求得理解的矛盾等，这是正常的成长现象。", mastered: false, collected: false },
  { id: "pol-7b-tb24-002", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "化解青春期心理矛盾的方法是（　　）", options: ["A. 自我封闭", "B. 向老师、家长求助", "C. 沉迷游戏", "D. 发泄情绪"], answer: "B", analysis: "化解青春期心理矛盾可以向老师、家长、朋友求助，也可以通过培养兴趣爱好、参加文体活动等方式转移注意力。", mastered: false, collected: false },
  { id: "pol-7b-tb24-003", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "「行己有耻」的底线意识要求我们（　　）", options: ["A. 触碰道德底线", "B. 树立底线意识，有所不为", "C. 违反法律", "D. 丧失良知"], answer: "B", analysis: "「行己有耻」要求我们树立底线意识，触碰道德底线的事情不做，违反法律的事情坚决不做，知廉耻、懂荣辱。", mastered: false, collected: false },
  { id: "pol-7b-tb24-004", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "榜样的力量表现在（　　）", options: ["A. 模仿一切", "B. 见贤思齐，汲取力量", "C. 盲目崇拜", "D. 失去自我"], answer: "B", analysis: "榜样的力量表现在见贤思齐，从榜样身上汲取精神力量，完善自我。但不是盲目崇拜，要保持独立思考。", mastered: false, collected: false },
  { id: "pol-7b-tb24-005", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "下列关于情绪作用的说法，正确的是（　　）", options: ["A. 情绪只会起消极作用", "B. 情绪可以起积极作用也可以起消极作用", "C. 情绪没有作用", "D. 情绪只会起积极作用"], answer: "B", analysis: "情绪具有双重作用，积极的情绪可以充实人的体力和精力，提高工作效率；消极的情绪会使人感到难受，降低自控力和活动能力。", mastered: false, collected: false },
  { id: "pol-7b-tb24-006", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "合理宣泄情绪的方法是（　　）", options: ["A. 向他人发脾气", "B. 运动出汗", "C. 摔打物品", "D. 伤害他人"], answer: "B", analysis: "合理宣泄情绪可以通过运动出汗、哭泣、倾诉等方式，但不能伤害自己和他人，不能破坏公共财物。", mastered: false, collected: false },
  { id: "pol-7b-tb24-007", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "美好情感获得的方式是（　　）", options: ["A. 沉迷网络", "B. 通过阅读、与人交往、参与有意义的活动", "C. 追求物质享受", "D. 自我封闭"], answer: "B", analysis: "美好情感可以通过阅读、与人交往、参与有意义的活动等方式获得，情由心生，美好情感是在感受生活中逐渐积累的。", mastered: false, collected: false },
  { id: "pol-7b-tb24-008", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "传递情感正能量的做法是（　　）", options: ["A. 传播负面情绪", "B. 关爱他人，帮助他人", "C. 冷漠对待他人", "D. 自私自利"], answer: "B", analysis: "传递情感正能量要求我们关爱他人、帮助他人，用自己的热情和行动来影响环境，在与他人的情感交流中传递美好的情感。", mastered: false, collected: false },
  { id: "pol-7b-tb24-009", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "集体规则的作用是（　　）", options: ["A. 限制自由", "B. 维护集体秩序和利益", "C. 增加麻烦", "D. 没有意义"], answer: "B", analysis: "集体规则维护集体秩序和利益，保障集体成员的正常学习和生活，每个成员都应自觉遵守集体规则。", mastered: false, collected: false },
  { id: "pol-7b-tb24-010", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "个人意愿与集体规则冲突时，应该（　　）", options: ["A. 坚持个人意愿", "B. 个人服从集体", "C. 无视规则", "D. 离开集体"], answer: "B", analysis: "当个人意愿与集体规则冲突时，应个人服从集体，理解集体要求的合理性，反思个人意愿的合理性和实现可能性，作出选择。", mastered: false, collected: false },
  { id: "pol-7b-tb24-011", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "集体建设需要（　　）", options: ["A. 个人努力", "B. 每个成员的智慧和力量", "C. 少数人参与", "D. 被动接受"], answer: "B", analysis: "集体建设需要每个成员的智慧和力量，每个人都自觉参与集体建设，为集体出力，集体才能更好地发展。", mastered: false, collected: false },
  { id: "pol-7b-tb24-012", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "在集体中，个人发展表现为（　　）", options: ["A. 突出个人", "B. 在集体中完善自我", "C. 与集体对立", "D. 脱离集体"], answer: "B", analysis: "在集体中，个人应通过参与集体活动完善自我，发展个性，集体为个人发展提供平台和机会。", mastered: false, collected: false },
  { id: "pol-7b-tb24-013", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "法律的特征是（　　）", options: ["A. 由国家制定或认可", "B. 随意规定", "C. 个人制定", "D. 不具有强制性"], answer: "A", analysis: "法律是由国家制定或认可、由国家强制力保证实施、对全体社会成员具有普遍约束力的行为规范，这是法律的主要特征。", mastered: false, collected: false },
  { id: "pol-7b-tb24-014", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "single", stem: "未成年人的特殊保护包括（　　）", options: ["A. 家庭保护、学校保护、社会保护、网络保护、政府保护、司法保护", "B. 只有家庭保护", "C. 只有学校保护", "D. 没有特殊保护"], answer: "A", analysis: "未成年人保护法规定了家庭保护、学校保护、社会保护、网络保护、政府保护、司法保护六道防线，全方位保护未成年人。", mastered: false, collected: false },
  { id: "pol-7b-tb24-015", subject: "politics", grade: "七年级下册", version: "统编版（2024）", type: "judge", stem: "未成年人犯罪不需要承担法律责任。", options: ["A. 正确", "B. 错误"], answer: "B", analysis: "未成年人犯罪也需要承担法律责任，根据刑法规定，已满12周岁的人犯故意杀人等严重罪行应负刑事责任，但可从轻或减轻处罚。", mastered: false, collected: false },

  // ===== 道法 统编版（五四学制）=====
  { id: "pol-7b-tb54-001", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "青春期的身体变化主要表现在（　　）", options: ["A. 身体外形的变化", "B. 内部器官的完善", "C. 性机能的成熟", "D. 以上都是"], answer: "D", analysis: "青春期身体变化主要表现在三个方面：身体外形的变化、内部器官的完善、性机能的成熟，这是正常的生理现象。", mastered: false, collected: false },
  { id: "pol-7b-tb54-002", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "对待青春期心理矛盾的正确态度是（　　）", options: ["A. 焦虑恐惧", "B. 正视矛盾，积极面对", "C. 逃避现实", "D. 自暴自弃"], answer: "B", analysis: "青春期心理矛盾是正常的成长现象，应正视矛盾、积极面对，通过适当的方式化解矛盾，促进心理健康发展。", mastered: false, collected: false },
  { id: "pol-7b-tb54-003", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "发展独立思维的表现是（　　）", options: ["A. 排斥他人意见", "B. 独立思考，不盲从", "C. 固执己见", "D. 反抗权威"], answer: "B", analysis: "发展独立思维表现为独立思考、不盲从，能理性分析问题，但不排斥他人合理意见，不是固执己见或反抗权威。", mastered: false, collected: false },
  { id: "pol-7b-tb54-004", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "培养批判性思维的方法是（　　）", options: ["A. 怀疑一切", "B. 敢于质疑，合理表达", "C. 否定他人", "D. 反对一切"], answer: "B", analysis: "培养批判性思维要敢于质疑、合理表达，对问题有自己独立的见解，但不是怀疑一切或否定他人，要建设性地提出观点。", mastered: false, collected: false },
  { id: "pol-7b-tb54-005", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "「止于至善」的实践要求是（　　）", options: ["A. 好高骛远", "B. 从小事做起，积善成德", "C. 追求完美", "D. 苛求自己"], answer: "B", analysis: "「止于至善」要求从小事做起，积善成德，向榜样学习，见贤思齐，养德修身，追求更高的道德境界。", mastered: false, collected: false },
  { id: "pol-7b-tb54-006", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "面对挫折，正确的做法是（　　）", options: ["A. 自暴自弃", "B. 调整心态，勇敢面对", "C. 逃避现实", "D. 怨天尤人"], answer: "B", analysis: "面对挫折应调整心态、勇敢面对，分析原因，寻找解决办法，培养坚强的意志和乐观向上的生活态度。", mastered: false, collected: false },
  { id: "pol-7b-tb54-007", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "下列关于情绪调节的说法，正确的是（　　）", options: ["A. 压抑情绪", "B. 学会调节情绪，做情绪的主人", "C. 随意发泄", "D. 不理会情绪"], answer: "B", analysis: "应学会调节情绪，做情绪的主人，通过转移注意、合理宣泄、改变认知评价等方法调节情绪，保持积极乐观的心态。", mastered: false, collected: false },
  { id: "pol-7b-tb54-008", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "情感的作用是（　　）", options: ["A. 影响判断和选择", "B. 影响行为", "C. 丰富生活", "D. 以上都是"], answer: "D", analysis: "情感影响我们的判断和选择，影响我们的行为，丰富我们的生活，情感伴随着情绪反应逐渐积累和发展。", mastered: false, collected: false },
  { id: "pol-7b-tb54-009", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "集体对个人成长的作用是（　　）", options: ["A. 限制个人发展", "B. 提供平台，促进个人成长", "C. 与个人对立", "D. 没有影响"], answer: "B", analysis: "集体为个人成长提供平台和机会，在集体中可以学习他人长处，完善自我，发展个性，培养合作精神。", mastered: false, collected: false },
  { id: "pol-7b-tb54-010", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "在集体中，个人应该（　　）", options: ["A. 突出自我", "B. 个人利益服从集体利益", "C. 只顾自己", "D. 与集体对抗"], answer: "B", analysis: "在集体中，个人利益应服从集体利益，处理好个人与集体的关系，自觉维护集体荣誉和利益，为集体建设贡献力量。", mastered: false, collected: false },
  { id: "pol-7b-tb54-011", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "当个人利益与集体利益发生冲突时，正确的做法是（　　）", options: ["A. 坚持个人利益", "B. 自觉让个人利益服从集体利益", "C. 损害集体利益", "D. 离开集体"], answer: "B", analysis: "当个人利益与集体利益发生冲突时，应自觉让个人利益服从集体利益，这是集体主义精神的表现。", mastered: false, collected: false },
  { id: "pol-7b-tb54-012", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "法律的规范作用表现在（　　）", options: ["A. 规定权利义务", "B. 维护社会秩序", "C. 解决纠纷", "D. 以上都是"], answer: "D", analysis: "法律的规范作用表现在规定权利和义务、维护社会秩序、解决纠纷、制裁违法行为等方面，为人们的行为提供准则。", mastered: false, collected: false },
  { id: "pol-7b-tb54-013", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "法律保护作用表现在（　　）", options: ["A. 保护公民合法权益", "B. 限制公民自由", "C. 取消公民权利", "D. 增加公民义务"], answer: "A", analysis: "法律的保护作用表现在法律通过规定权利和义务，保护公民的合法权益，为公民的生活和发展提供法律保障。", mastered: false, collected: false },
  { id: "pol-7b-tb54-014", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "single", stem: "未成年人在受到不法侵害时，应该（　　）", options: ["A. 忍气吞声", "B. 以暴制暴", "C. 及时寻求法律帮助", "D. 私了"], answer: "C", analysis: "未成年人在受到不法侵害时，应及时寻求法律帮助，向公安机关报案，运用法律武器维护自己的合法权益。", mastered: false, collected: false },
  { id: "pol-7b-tb54-015", subject: "politics", grade: "七年级下册", version: "统编版（五四学制）", type: "judge", stem: "未成年人应该增强自我保护意识，提高自我保护能力。", options: ["A. 正确", "B. 错误"], answer: "A", analysis: "未成年人应该增强自我保护意识，提高自我保护能力，学会用法律武器保护自己，防范不法侵害，维护自身合法权益。", mastered: false, collected: false },
];










